function parse(text) {
  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;

  const finishField = () => {
    row.push(field);
    field = '';
  };
  const finishRow = () => {
    finishField();
    rows.push(row);
    row = [];
  };

  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (inQuotes) {
      if (ch !== '"') {
        field += ch;
      } else if (text[i + 1] === '"') {
        field += '"';
        i++;
      } else {
        inQuotes = false;
      }
    } else if (ch === '"') {
      inQuotes = true;
    } else if (ch === ',') {
      finishField();
    } else if (ch === '\n') {
      finishRow();
    } else if (ch === '\r') {
      if (text[i + 1] === '\n') {
        i++;
      }
      finishRow();
    } else {
      field += ch;
    }
  }

  if (field !== '' || row.length > 0) {
    finishRow();
  }
  return rows;
}

function columnWidths(rows) {
  const widths = [];
  for (const row of rows) {
    row.forEach((cell, c) => {
      if (widths[c] === undefined || cell.length > widths[c]) {
        widths[c] = cell.length;
      }
    });
  }
  return widths;
}

function formatTable(rows) {
  const widths = columnWidths(rows);
  return rows
    .map((row) =>
      row
        .map((cell, c) => (c === row.length - 1 ? cell : cell.padEnd(widths[c])))
        .join(' | ')
    )
    .join('\n');
}

const sample =
  'year,make,model,description\n' +
  '1997,Ford,E350,"ac, abs, moon"\r\n' +
  '1999,Chevy,"Venture ""Extended Edition""","line one\nline two"\n';

const parsed = parse(sample);
console.log(`rows: ${parsed.length}`);
parsed.forEach((row, i) => {
  console.log(`row ${i} has ${row.length} field(s)`);
});
console.log(formatTable(parsed));

