const TAPE_SIZE = 300;

function buildJumpTable(instructions) {
  const table = new Map();
  const stack = [];
  for (let i = 0; i < instructions.length; i++) {
    const ch = instructions[i];
    if (ch === '[') {
      stack.push(i);
    } else if (ch === ']') {
      if (stack.length === 0) {
        throw new SyntaxError('unmatched "]" at index ' + i);
      }
      const open = stack.pop();
      table.set(open, i);
      table.set(i, open);
    }
  }
  if (stack.length !== 0) {
    throw new SyntaxError('unmatched "[" at index ' + stack[0]);
  }
  return table;
}

function execute(instructions) {
  if (typeof instructions !== 'string') {
    throw new TypeError('instructions must be a string');
  }
  const jumps = buildJumpTable(instructions);
  const tape = new Array(TAPE_SIZE).fill(0);
  let pointer = 0;
  let ip = 0;
  let output = '';
  while (ip < instructions.length) {
    const ch = instructions[ip];
    if (ch === '>') {
      pointer = (pointer + 1) % TAPE_SIZE;
    } else if (ch === '<') {
      pointer = (pointer + TAPE_SIZE - 1) % TAPE_SIZE;
    } else if (ch === '+') {
      tape[pointer] = (tape[pointer] + 1) & 0xff;
    } else if (ch === '-') {
      tape[pointer] = (tape[pointer] + 0xff) & 0xff;
    } else if (ch === '.') {
      output += String.fromCharCode(tape[pointer]);
    } else if (ch === '[') {
      if (tape[pointer] === 0) {
        ip = jumps.get(ip);
      }
    } else if (ch === ']') {
      if (tape[pointer] !== 0) {
        ip = jumps.get(ip);
      }
    }
    ip++;
  }
  return output;
}

function escapeOutput(text) {
  let escaped = '';
  for (const ch of text) {
    const code = ch.charCodeAt(0);
    if (code === 10) {
      escaped += '\\n';
    } else if (code === 9) {
      escaped += '\\t';
    } else if (code < 32 || code === 127) {
      escaped += '\\x' + code.toString(16).padStart(2, '0');
    } else {
      escaped += ch;
    }
  }
  return escaped;
}

function report(label, program) {
  const output = execute(program);
  if (output.length === 0) {
    return label + ': (no output)';
  }
  return label + ': ' + escapeOutput(output);
}

console.log(report('sixty-five', '+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++.'));
console.log(report('countdown', '++++++++[>++++++<-]>.-.-.'));
console.log(report('silent', '++++>>++<<--'));

