const CR = '\r';
const LF = '\n';

function findLineEnd(text, start) {
  for (let i = start; i < text.length - 1; i += 1) {
    if (text[i] !== CR) continue;
    if (text[i + 1] === LF) return i;
  }
  return -1;
}

function isBlankLine(line) {
  if (line.length === 0) return true;
  if (line.length > 1) return false;
  return line[0] === CR;
}

function classifyStatus(code) {
  if (code === '200') return 'OK';
  if (code === '400') return 'Bad Request';
  if (code === '500') return 'Server Error';
  return 'Unrecognized';
}

function extractStatusCode(statusLine) {
  const firstSpace = statusLine.indexOf(' ');
  if (firstSpace === -1) return '';
  const rest = statusLine.slice(firstSpace + 1);
  const secondSpace = rest.indexOf(' ');
  return secondSpace === -1 ? rest : rest.slice(0, secondSpace);
}

function splitHeader(line) {
  const colon = line.indexOf(':');
  if (colon === -1) return null;
  const key = line.slice(0, colon).trim().toLowerCase();
  const value = line.slice(colon + 1).trim();
  return { key, value };
}

function isWantedHeader(key) {
  if (key === 'content-type') return true;
  if (key === 'content-length') return true;
  return key === 'connection';
}

function parsehttp(response) {
  const statusEnd = findLineEnd(response, 0);
  if (statusEnd === -1) return [];
  const code = extractStatusCode(response.slice(0, statusEnd));
  const result = [code];
  let pos = statusEnd + 2;
  while (pos < response.length) {
    let end = findLineEnd(response, pos);
    if (end === -1) end = response.length;
    const line = response.slice(pos, end);
    pos = end + 2;
    if (isBlankLine(line)) break;
    const header = splitHeader(line);
    if (header === null) continue;
    if (isWantedHeader(header.key)) result.push(header.value);
  }
  return result;
}

const raw =
  'HTTP/1.1 200 OK\r\n' +
  'Content-Type: text/html\r\n' +
  'Server: demo\r\n' +
  'Content-Length: 42\r\n' +
  'Connection: keep-alive\r\n' +
  '\r\n' +
  '<html></html>';

const parsed = parsehttp(raw);
console.log(parsed);
console.log('status meaning:', classifyStatus(parsed[0]));
console.log('headers found:', parsed.length - 1);
if (parsed[0] !== '200') console.log('request did not succeed');

