const CROSS = 'X';
const NAUGHT = 'O';
const EMPTY = ' ';

function isKnownSquare(square) {
  if (square === CROSS) {
    return true;
  }
  if (square === NAUGHT) {
    return true;
  }
  return square === EMPTY;
}

function validateShape(board) {
  if (!Array.isArray(board) || board.length !== 3) {
    throw new Error('board must have exactly three rows');
  }
  for (const row of board) {
    if (!Array.isArray(row) || row.length !== 3) {
      throw new Error('each row must have exactly three squares');
    }
    for (const square of row) {
      if (!isKnownSquare(square)) {
        throw new Error(`unexpected square value: ${JSON.stringify(square)}`);
      }
    }
  }
}

function countMark(board, mark) {
  let total = 0;
  for (const row of board) {
    for (const square of row) {
      if (square === mark) {
        total += 1;
      }
    }
  }
  return total;
}

function collectLines(board) {
  const lines = [];
  for (let i = 0; i < 3; i += 1) {
    lines.push([board[i][0], board[i][1], board[i][2]]);
    lines.push([board[0][i], board[1][i], board[2][i]]);
  }
  lines.push([board[0][0], board[1][1], board[2][2]]);
  lines.push([board[0][2], board[1][1], board[2][0]]);
  return lines;
}

function hasWinningLine(board, mark) {
  return collectLines(board).some((line) => line.every((square) => square === mark));
}

function analyze(board) {
  validateShape(board);
  const crosses = countMark(board, CROSS);
  const naughts = countMark(board, NAUGHT);
  if (crosses - naughts > 1 || naughts > crosses) {
    return 'invalid board';
  }
  const crossWins = hasWinningLine(board, CROSS);
  const naughtWins = hasWinningLine(board, NAUGHT);
  if (crossWins && naughtWins) {
    return 'invalid board';
  }
  if (crossWins) {
    return 'cross wins';
  }
  if (naughtWins) {
    return 'naught wins';
  }
  if (countMark(board, EMPTY) === 0) {
    return 'draw';
  }
  return 'game is ongoing';
}

function report(label, board) {
  let verdict;
  try {
    verdict = analyze(board);
  } catch (error) {
    verdict = `rejected: ${error.message}`;
  }
  console.log(`${label}: ${verdict}`);
}

report('top row crosses', [
  ['X', 'X', 'X'],
  ['O', 'O', ' '],
  [' ', ' ', ' '],
]);
report('naught column', [
  ['O', 'X', 'X'],
  ['O', 'X', ' '],
  ['O', ' ', 'X'],
]);
report('full board', [
  ['X', 'O', 'X'],
  ['X', 'O', 'O'],
  ['O', 'X', 'X'],
]);
report('short row', [['X', 'O'], ['X', 'O', ' '], [' ', ' ', ' ']]);

module.exports = { analyze };

