function transcribeBase(base) {
  if (base === 'A') return 'U';
  if (base === 'C') return 'G';
  if (base === 'G') return 'C';
  if (base === 'T') return 'A';
  return null;
}

function isIgnored(character) {
  if (character === '-') return true;
  return character === ' ';
}

function analyzedna(sequence) {
  if (typeof sequence !== 'string') {
    throw new TypeError('analyzedna expects a string of nucleotides');
  }
  let rna = '';
  let errors = 0;
  for (let i = 0; i < sequence.length; i += 1) {
    const character = sequence[i];
    if (isIgnored(character)) {
      continue;
    }
    const complement = transcribeBase(character);
    if (complement === null) {
      errors += 1;
    } else {
      rna += complement;
    }
  }
  return [rna, errors];
}

function baseCounts(rna) {
  const counts = { A: 0, C: 0, G: 0, U: 0 };
  for (const base of rna) {
    counts[base] += 1;
  }
  return counts;
}

function gcContent(rna) {
  if (rna.length === 0) {
    return 0;
  }
  const counts = baseCounts(rna);
  return (counts.G + counts.C) / rna.length;
}

function describeQuality(errors) {
  if (errors === 0) return 'clean';
  if (errors <= 2) return 'minor anomalies';
  return 'heavily corrupted';
}

function reportSequence(label, sequence) {
  const [rna, errors] = analyzedna(sequence);
  const lines = [label + ': ' + (rna.length === 0 ? '(empty transcription)' : rna)];
  lines.push('  errors: ' + errors + ' (' + describeQuality(errors) + ')');
  lines.push('  GC content: ' + (gcContent(rna) * 100).toFixed(1) + '%');
  const counts = baseCounts(rna);
  const missing = Object.keys(counts).filter(function (base) {
    return counts[base] === 0;
  });
  if (missing.length !== 0) {
    lines.push('  absent bases: ' + missing.join(', '));
  }
  return lines.join('\n');
}

function main() {
  const samples = [
    ['sample 1', 'ACGT-TTAC GGX'],
    ['sample 2', 'GGG CCC AAA TTT'],
    ['sample 3', 'ZZ-- Q!A']
  ];
  for (const [label, sequence] of samples) {
    console.log(reportSequence(label, sequence));
  }
}

main();

