  const samples = [
    'a &lt; b &amp;&amp; b &gt; c',
    '&quot;Hello&quot; &apos;World&apos;',
    'Copyright&nbsp;&copy;&nbsp;2026',
    '&unknown; stays, &broken also stays'
  ];
