'use strict';

const OPERATORS = ['+', '-', '*', '/', '%', '^'];

function isNumberChar(ch) {
  const isDot = ch === '.';
  return isDot || (ch >= '0' && ch <= '9');
}

function startsTerm(tokens) {
  if (tokens.length === 0) return true;
  const last = tokens[tokens.length - 1];
  return typeof last === 'string';
}

function tokenize(expression) {
  const tokens = [];
  let buffer = '';
  for (let i = 0; i < expression.length; i++) {
    const ch = expression[i];
    if (isNumberChar(ch)) {
      buffer += ch;
    } else if (OPERATORS.indexOf(ch) !== -1) {
      const empty = buffer === '';
      if (empty && ch === '-' && startsTerm(tokens)) {
        buffer = '-';
      } else {
        if (!empty) tokens.push(Number(buffer));
        buffer = '';
        tokens.push(ch);
      }
    }
  }
  if (buffer !== '') tokens.push(Number(buffer));
  return tokens;
}

function applyOperator(op, a, b) {
  if (op === '+') return a + b;
  if (op === '-') return a - b;
  if (op === '*') return a * b;
  if (op === '^') return Math.pow(a, b);
  const divisorIsZero = b === 0;
  if (divisorIsZero) return 0;
  if (op === '/') return a / b;
  if (op === '%') return a % b;
  return 0;
}

function powerPass(tokens) {
  const out = tokens.slice();
  let idx = out.lastIndexOf('^');
  while (idx > 0) {
    const left = out[idx - 1];
    const right = out[idx + 1];
    if (typeof left !== 'number') break;
    if (typeof right !== 'number') break;
    out.splice(idx - 1, 3, applyOperator('^', left, right));
    idx = out.lastIndexOf('^');
  }
  return out;
}

function binaryPass(tokens, ops) {
  const result = [tokens[0]];
  let i = 1;
  while (i < tokens.length) {
    const op = tokens[i];
    const right = tokens[i + 1];
    if (typeof right !== 'number') {
      result.push(op);
      i += 1;
    } else if (ops.indexOf(op) !== -1) {
      result.push(applyOperator(op, result.pop(), right));
      i += 2;
    } else {
      result.push(op, right);
      i += 2;
    }
  }
  return result;
}

function calculate(expression) {
  if (typeof expression !== 'string') return 0;
  const tokens = tokenize(expression);
  if (tokens.length === 0) return 0;
  let values = powerPass(tokens);
  values = binaryPass(values, ['*', '/', '%']);
  values = binaryPass(values, ['+', '-']);
  if (values.length !== 1) return 0;
  return values[0];
}

function formatResult(value) {
  if (value === Math.trunc(value)) return String(value);
  return value.toFixed(4);
}

function main() {
  const samples = ['2+3*4', '10/4', '7%0', '2^3^2', '-5+12*2-8/2', '100/0+3'];
  for (const sample of samples) {
    console.log(sample + ' = ' + formatResult(calculate(sample)));
  }
}

