function isDigits(card) {
  if (typeof card !== 'string') {
    return false;
  }
  for (let i = 0; i < card.length; i++) {
    const code = card.charCodeAt(i);
    if (code < 48 || code > 57) {
      return false;
    }
  }
  return card.length !== 0;
}

function isAmex(card) {
  if (card.length !== 15) {
    return false;
  }
  const prefix = card.slice(0, 2);
  if (prefix === '34') {
    return true;
  }
  return prefix === '37';
}

function isVisa(card) {
  if (card.length !== 16) {
    return false;
  }
  return card.charAt(0) === '4';
}

function isMastercard(card) {
  if (card.length !== 16) {
    return false;
  }
  if (card.charAt(0) !== '5') {
    return false;
  }
  const second = card.charAt(1);
  return second >= '1' && second <= '5';
}

function isDiscover(card) {
  if (card.length !== 16) {
    return false;
  }
  return card.slice(0, 4) === '6011';
}

function verify(card) {
  if (isDigits(card) === false) {
    return 'unknown';
  }
  if (isAmex(card)) {
    return 'american express';
  }
  if (isVisa(card)) {
    return 'visa';
  }
  if (isMastercard(card)) {
    return 'mastercard';
  }
  if (isDiscover(card)) {
    return 'discover';
  }
  return 'unknown';
}

function describe(card) {
  const network = verify(card);
  if (network === 'unknown') {
    return card + ' -> unrecognised issuer';
  }
  return card + ' -> ' + network;
}

