function isSkippable(ch) {
  if (ch === ' ') return true;
  if (ch === '\t') return true;
  return ch === '\n';
}

function readTag(text, start) {
  let i = start + 1;
  let name = '';
  while (i < text.length) {
    const ch = text[i];
    if (ch === '>') {
      return { name: name, end: i };
    }
    name += ch;
    i += 1;
  }
  return null;
}

function validatexml(text) {
  if (typeof text !== 'string') {
    throw new TypeError('validatexml expects a string');
  }
  const stack = [];
  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i];
    if (isSkippable(ch)) {
      continue;
    }
    if (ch !== '<') {
      continue;
    }
    const tag = readTag(text, i);
    if (tag === null) {
      return false;
    }
    i = tag.end;
    let name = tag.name;
    if (name[0] === '/') {
      name = name.slice(1);
      if (stack.length === 0) {
        return false;
      }
      if (stack[stack.length - 1] !== name) {
        return false;
      }
      stack.pop();
    } else {
      stack.push(name);
    }
  }
  return stack.length === 0;
}

function formatReport(text, valid) {
  const shown = text.length > 40 ? text.slice(0, 37) + '...' : text;
  const verdict = valid === true ? 'true ' : 'false';
  return verdict + '  ' + shown;
}

function main() {
  const samples = [
    '<html><head><title>Test</title></head><body>Hello</body></html>',
    '<a><b></a></b>',
    '<one>\t<two>\n</two>  </one>',
    '<open><inner></inner>',
    '</early><late>',
    '<broken'
  ];
  let wellNested = 0;
  for (const sample of samples) {
    const valid = validatexml(sample);
    if (valid) {
      wellNested += 1;
    }
    console.log(formatReport(sample, valid));
  }
  console.log(wellNested + ' of ' + samples.length + ' samples are correctly nested');
}

main();

