  if (MODIFIERS.indexOf(modifier) == -1) {
    throw new RangeError(`note "${note}" has an unknown modifier "${modifier}"`);
  }
  if (octaveChar < '0' || octaveChar > '9') {
    throw new RangeError(`note "${note}" has a non-digit octave`);
  }
  const octave = Number(octaveChar);
  if (letter == 'R') {
    if (octave != 0) {
      throw new RangeError(`rest "${note}" must use octave 0`);
    }
    return;
  }
  if (BASE_VALUES[letter] == undefined) {
    throw new RangeError(`note "${note}" has an unknown base letter "${letter}"`);
  }
}

function notePitch(note) {
  validateNote(note);
  const letter = note[0];
  const octave = Number(note[2]);
  if (letter == 'R') {
    return 0;
  }
  const base = BASE_VALUES[letter] + modifierDelta(note[1], letter, octave);
  return base + octave * 12;
}

function parse(notes) {
  let totalPitch = 0;
  for (const note of notes) {
    totalPitch += notePitch(note);
  }
  return totalPitch;
}

function report(notes) {
  const lines = notes.map((note) => {
    const pitch = notePitch(note);
    const label = pitch == 0 ? 'silent' : `pitch ${pitch}`;
    return `${note} -> ${label}`;
  });
  lines.push(`total -> ${parse(notes)}`);
  return lines.join('\n');
}

