const RULES = [
  { name: 'temperature', value: 0, weight: 1 },
  { name: 'pressure', value: 100, weight: 1 },
  { name: 'radiation', value: 50, weight: 2 },
  { name: 'oxygen', value: 0, weight: 0 },
  { name: 'fuel', value: 10, weight: 1 },
  { name: 'voltage', value: 200, weight: 3 }
];

function isValidPacket(packet) {
  if (!Array.isArray(packet)) {
    return false;
  }
  if (packet.length !== 2) {
    return false;
  }
  if (typeof packet[0] !== 'string') {
    return false;
  }
  return typeof packet[1] === 'number' && Number.isFinite(packet[1]);
}

function matchRule(name, value) {
  for (const rule of RULES) {
    if (rule.name !== name) {
      continue;
    }
    if (rule.value === value) {
      return rule;
    }
  }
  return null;
}

function parse(packets) {
  let warnings = 0;

  for (const packet of packets) {
    if (!isValidPacket(packet)) {
      continue;
    }

    const rule = matchRule(packet[0], packet[1]);
    if (rule === null) {
      continue;
    }
    if (rule.name === 'oxygen') {
      return ['critical', warnings];
    }
    warnings += rule.weight;
  }

  return ['stable', warnings];
}

function formatReport(result) {
  const status = result[0];
  const warnings = result[1];
  const label = warnings === 1 ? 'warning' : 'warnings';
  const prefix = status === 'critical' ? 'ABORT' : 'OK';
  return prefix + ': ' + status + ' with ' + warnings + ' ' + label;
}

function readSample(lines) {
  const packets = [];

  for (const line of lines) {
    const parts = line.split(',');
    if (parts.length !== 2) {
      continue;
    }
    const name = parts[0].trim();
    const value = Number(parts[1].trim());
    if (name === '') {
      continue;
    }
    if (!Number.isNaN(value)) {
      packets.push([name, value]);
    }
  }

  return packets;
}

const telemetry = readSample([
  'temperature, 0',
  'pressure, 100',
  'radiation, 50',
  'fuel, 10',
  'voltage, 200',
  'humidity, 40'
]);

console.log(formatReport(parse(telemetry)));

