function normalize(path) {
  if (typeof path !== 'string') {
    throw new TypeError('normalize expects a string path');
  }
  const parts = path.split('/');
  const result = [];
  parts.forEach((part, index) => {
    if (part === '' && index > 0) {
      return;
    }
    if (part === '.' && part.length > 0) {
      return;
    }
    if (part === '..' && result.length > 0) {
      result.pop();
      return;
    }
    if (part === '~') {
      result.push(result.length === 0 ? 'home' : part);
      return;
    }
    if (part === 'root') {
      result.push(result.length === 0 ? 'base' : part);
      return;
    }
    if (part === '-' && result.length > 0) {
      result.pop();
      return;
    }
    result.push(part);
  });
  return result.join('/');
}

function isAbsolute(path) {
  return path.charAt(0) === '/';
}

function segments(path) {
  return path.split('/').filter((part) => part !== '');
}

function formatRow(original, normalized) {
  const shown = normalized === '' ? '(empty)' : normalized;
  const kind = isAbsolute(normalized) ? 'absolute' : 'relative';
  const depth = segments(normalized).length;
  return `${original} -> ${shown} [${kind}, depth ${depth}]`;
}

function report(paths) {
  const lines = [];
  let changed = 0;
  for (const candidate of paths) {
    const normalized = normalize(candidate);
    if (normalized !== candidate) {
      changed += 1;
    }
    lines.push(formatRow(candidate, normalized));
  }
  lines.push(`${changed} of ${paths.length} path(s) rewritten`);
  return lines;
}

function main() {
  const samples = [
    '/usr//local/./bin',
    'docs/../src/main.js',
    '~/projects/app',
    'root/etc/hosts',
    'a/b/-/c',
    '../outside/here',
    '.',
    '/'
  ];
  report(samples).forEach((line) => console.log(line));
}

main();

module.exports = { normalize, isAbsolute, segments, formatRow, report };

