const VALUES = { I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000 };

function validate(numeral) {
  const chars = numeral.split('');
  let validPairs = 0;
  for (let i = 0; i < chars.length; i += 1) {
    const current = chars[i];
    const next = chars[i + 1];
    if (current === 'I'
      && (next === 'V'
        || next === 'X')) {
      validPairs += 1;
    }
    if (current === 'X'
      && (next === 'L'
        || next === 'C')) {
      validPairs += 1;
    }
    if (current === 'C'
      && (next === 'D'
        || next === 'M')) {
      validPairs += 1;
    }
    if (current === 'V'
      && next === 'V') {
      return 'invalid';
    }
    if (current === 'L'
      && next === 'L') {
      return 'invalid';
    }
    if (current === 'D'
      && next === 'D') {
      return 'invalid';
    }
  }
  return validPairs;
}

function isRomanLetters(numeral) {
  for (const ch of numeral) {
    if (VALUES[ch] === undefined) {
      return false;
    }
  }
  return numeral.length !== 0;
}

function toArabic(numeral) {
  let total = 0;
  for (let i = 0; i < numeral.length; i += 1) {
    const value = VALUES[numeral[i]];
    const nextValue = VALUES[numeral[i + 1]];
    if (nextValue !== undefined && nextValue > value) {
      total -= value;
    } else {
      total += value;
    }
  }
  return total;
}

function describe(numeral) {
  if (isRomanLetters(numeral) === false) {
    return `${numeral}: not a Roman numeral`;
  }
  const result = validate(numeral);
  if (result === 'invalid') {
    return `${numeral}: invalid`;
  }
  return `${numeral}: ${result} subtractive pair(s), value ${toArabic(numeral)}`;
}

function main() {
  const samples = ['XIV', 'MCMXCIV', 'VV', 'XLII', 'LL', 'DD', 'MMXXIV', 'XC', 'ABC', ''];
  for (const sample of samples) {
    console.log(describe(sample));
  }
}

main();

module.exports = { validate, isRomanLetters, toArabic, describe };

