function validateTransaction(entry, index) {
  if (Array.isArray(entry) !== true) {
    throw new TypeError('Transaction ' + index + ' must be a list');
  }
  if (entry.length !== 2) {
    throw new RangeError('Transaction ' + index + ' must hold an action and a category');
  }
  const action = entry[0];
  if (typeof action !== 'string') {
    throw new TypeError('Action of transaction ' + index + ' must be a string');
  }
  const category = entry[1];
  if (typeof category !== 'string') {
    throw new TypeError('Category of transaction ' + index + ' must be a string');
  }
  return [action, category];
}

function manage(transactions) {
  let penaltyFee = 0;
  let borrowed = 0;
  for (let i = 0; i < transactions.length; i += 1) {
    const pair = validateTransaction(transactions[i], i);
    const action = pair[0];
    const category = pair[1];
    if (action === 'borrow') {
      if (category === 'reference') {
        penaltyFee += 5;
      } else if (category === 'fiction') {
        borrowed += 1;
      }
    } else if (action === 'return') {
      if (borrowed > 0) {
        borrowed -= 1;
      }
    } else if (action === 'lose') {
      if (category === 'fiction') {
        penaltyFee += 20;
        borrowed -= 1;
      }
    } else if (action === 'renew') {
      if (category === 'reference') {
        penaltyFee += 2;
      }
    } else if (action === 'reserve') {
      if (borrowed === 0) {
        penaltyFee += 1;
      }
    }
  }
  return [borrowed, penaltyFee];
}

function describe(result) {
  const borrowed = result[0];
  const penaltyFee = result[1];
  const bookWord = borrowed === 1 ? 'book' : 'books';
  const feeText = penaltyFee === 0 ? 'no penalty' : penaltyFee + ' owed';
  return borrowed + ' ' + bookWord + ' out, ' + feeText;
}

function report(sessions) {
  const lines = [];
  const names = Object.keys(sessions);
  for (const name of names) {
    const result = manage(sessions[name]);
    lines.push(name + ': ' + describe(result));
  }
  return lines.join('\n');
}

const sessions = {
  ana: [['borrow', 'fiction'], ['borrow', 'reference'], ['renew', 'reference'], ['return', 'fiction']],
  ben: [['reserve', 'fiction'], ['borrow', 'fiction'], ['lose', 'fiction'], ['reserve', 'fiction']],
  cleo: [['borrow', 'fiction'], ['borrow', 'fiction'], ['return', 'fiction']]
};

console.log(report(sessions));
console.log(manage(sessions.ana).join(', '));

