function normalizeOrder(order) {
  return {
    size: String(order.size || '').trim().toLowerCase(),
    drink: String(order.drink || '').trim().toLowerCase(),
    milk: String(order.milk || '').trim().toLowerCase()
  };
}

function basePrice(order) {
  const { size, drink, milk } = order;

  if (size === 'large' && drink === 'latte') {
    return 5;
  }
  if (size === 'small' && drink === 'espresso') {
    return 3;
  }
  if (drink === 'macchiato' && milk === 'oat') {
    return 6;
  }
  if (size === 'medium' && drink === 'americano') {
    return 4;
  }
  if (drink === 'cappuccino' && milk === 'soy') {
    return 5;
  }
  return 0;
}

function surcharge(order) {
  if (order.milk !== 'almond') {
    return 0;
  }
  return order.size === 'large' ? 1 : 0;
}

function priceOf(order) {
  const normalized = normalizeOrder(order);
  return basePrice(normalized) + surcharge(normalized);
}

function calculate(orders) {
  if (!Array.isArray(orders)) {
    throw new TypeError('calculate expects an array of order records');
  }

  let total = 0;
  for (const order of orders) {
    if (order === null || typeof order !== 'object') {
      throw new TypeError('each order must be an object');
    }
    total += priceOf(order);
  }
  return total;
}

function describe(order) {
  const normalized = normalizeOrder(order);
  const price = priceOf(order);
  const milkLabel = normalized.milk === '' ? 'no milk' : normalized.milk + ' milk';
  const parts = [normalized.size, normalized.drink, milkLabel].filter(part => part !== '');
  const label = parts.join(' ');
  return label + ': $' + price;
}

function report(orders) {
  const lines = orders.map(describe);
  const total = calculate(orders);
  lines.push('TOTAL: $' + total);
  return lines.join('\n');
}

const tickets = [
  { size: 'large', drink: 'latte', milk: 'whole' },
  { size: 'small', drink: 'espresso', milk: '' },
  { size: 'large', drink: 'latte', milk: 'almond' },
  { size: 'medium', drink: 'macchiato', milk: 'oat' },
  { size: 'medium', drink: 'americano', milk: 'whole' },
  { size: 'small', drink: 'cappuccino', milk: 'soy' }
];

