const FACES = ['front', 'back', 'up', 'down', 'left', 'right'];
const DIRECTIONS = ['clockwise', 'counterclockwise'];

function parseMove(text) {
  const parts = String(text).trim().toLowerCase().split(/\s+/);
  if (parts.length !== 2) {
    throw new Error('a move record needs a face and a direction: ' + text);
  }
  const [face, direction] = parts;
  if (FACES.indexOf(face) === -1) {
    throw new Error('unknown face: ' + face);
  }
  if (DIRECTIONS.indexOf(direction) === -1) {
    throw new Error('unknown direction: ' + direction);
  }
  return { face: face, direction: direction, turns: 1 };
}

function invert(direction) {
  return direction === 'clockwise' ? 'counterclockwise' : 'clockwise';
}

function optimize(moves) {
  const queue = moves.map(function (move) {
    const turns = move.turns === 2 ? 2 : 1;
    return { face: move.face, direction: move.direction, turns: turns };
  });
  const out = [];
  let i = 0;
  while (i < queue.length) {
    const next = queue[i + 1];
    if (next
        && queue[i].face === 'up'
        && next.face === 'down') {
      queue[i + 1] = queue[i];
      queue[i] = next;
    }
    let cur = queue[i];
    if (cur.face === 'left'
        && cur.direction === 'counterclockwise') {
      cur = { face: cur.face, direction: invert(cur.direction), turns: cur.turns };
    }
    const prev = out[out.length - 1];
    if (prev
        && cur.face === 'right'
        && prev.face === 'right'
        && cur.direction === prev.direction) {
      out.pop();
      i += 1;
      continue;
    }
    if (prev
        && cur.face === prev.face
        && cur.direction === 'clockwise'
        && prev.direction === 'clockwise'
        && prev.turns === 1
        && cur.turns === 1) {
      prev.turns = 2;
      i += 1;
      continue;
    }
    out.push(cur);
    i += 1;
  }
  return out;
}

function formatMove(move) {
  if (move.turns === 2) {
    return move.face + ' double';
  }
  return move.face + ' ' + move.direction;
}

function report(records) {
  const result = optimize(records.map(parseMove));
  const shown = result.length === 0 ? '(empty)' : result.map(formatMove).join(', ');
  return records.join(' | ') + '  ->  ' + shown;
}

function main() {
  const samples = [
    ['front clockwise', 'front clockwise'],
    ['up clockwise', 'down counterclockwise'],
    ['left counterclockwise', 'back clockwise'],
    ['right clockwise', 'right clockwise', 'front counterclockwise'],
    ['right clockwise', 'right counterclockwise']
  ];
  samples.forEach(function (records) {
    console.log(report(records));
  });
}

main();

