const OBSTACLES = ['none', 'windmill', 'water', 'tunnel', 'ramp'];
const MAX_STROKES = 7;

function normalizeObstacle(raw) {
  if (raw == null) {
    return 'none';
  }
  const name = String(raw).trim().toLowerCase();
  if (name === '') {
    return 'none';
  }
  if (OBSTACLES.indexOf(name) === -1) {
    throw new Error('unknown obstacle: ' + raw);
  }
  return name;
}

function parseHole(record, index) {
  if (record == null) {
    throw new Error('hole ' + (index + 1) + ' is missing');
  }
  if (typeof record !== 'object') {
    throw new Error('hole ' + (index + 1) + ' is not a record');
  }
  const strokes = Number(record.strokes);
  const par = Number(record.par);
  if (Number.isInteger(strokes) !== true) {
    throw new Error('hole ' + (index + 1) + ' has a non-integer stroke count');
  }
  if (Number.isInteger(par) !== true) {
    throw new Error('hole ' + (index + 1) + ' has a non-integer par value');
  }
  if (strokes < 1 || strokes > MAX_STROKES) {
    throw new Error('hole ' + (index + 1) + ' strokes out of range');
  }
  return { strokes: strokes, par: par, obstacle: normalizeObstacle(record.obstacle) };
}

function holeValue(hole) {
  if (hole.strokes === 1) {
    if (hole.obstacle === 'windmill') {
      return -3;
    }
    if (hole.obstacle === 'none') {
      return -2;
    }
  }
  if (hole.strokes === hole.par) {
    if (hole.obstacle === 'water') {
      return 1;
    }
  }
  if (hole.strokes === hole.par + 1) {
    return 1;
  }
  if (hole.strokes === MAX_STROKES) {
    return 3;
  }
  return 0;
}

function score(holes) {
  if (Array.isArray(holes) !== true) {
    throw new Error('holes must be an array');
  }
  return holes.reduce(function (total, record, index) {
    return total + holeValue(parseHole(record, index));
  }, 0);
}

function report(holes) {
  const lines = holes.map(function (record, index) {
    const hole = parseHole(record, index);
    const value = holeValue(hole);
    const sign = value > 0 ? '+' : '';
    const label = value === 0 ? 'even' : sign + value;
    return 'Hole ' + (index + 1) + ' (' + hole.obstacle + '): ' + hole.strokes + ' strokes, par ' + hole.par + ' -> ' + label;
  });
  lines.push('Total: ' + score(holes));
  return lines.join('\n');
}

const card = [
  { strokes: 1, obstacle: 'windmill', par: 3 },
  { strokes: 1, obstacle: 'none', par: 2 },
  { strokes: 4, obstacle: 'water', par: 4 },
  { strokes: 5, obstacle: 'ramp', par: 4 },
  { strokes: 7, obstacle: 'tunnel', par: 5 },
  { strokes: 2, obstacle: 'tunnel', par: 4 }
];

console.log(report(card));

module.exports = { score: score, report: report, holeValue: holeValue };

