function normalizeRecord(record) {
  if (typeof record !== 'object') {
    throw new TypeError('each controller record must be an object');
  }
  if (record === null) {
    throw new TypeError('each controller record must be an object');
  }
  const button = typeof record.button === 'string' ? record.button.trim().toLowerCase() : '';
  const state = typeof record.state === 'string' ? record.state.trim().toLowerCase() : '';
  if (button === '') {
    throw new TypeError('controller record is missing a button name');
  }
  if (state === '') {
    throw new TypeError('controller record is missing a player state');
  }
  return { button: button, state: state };
}

function actionFor(button, state) {
  if (button === 'cross') {
    if (state === 'grounded') {
      return 'jump';
    }
    if (state === 'airborne') {
      return 'double jump';
    }
  }
  if (button === 'circle') {
    if (state === 'moving') {
      return 'slide';
    }
  }
  if (button === 'square') {
    return state === 'defending' ? 'parry' : 'unknown';
  }
  if (button === 'triangle') {
    return state === 'idle' ? 'rest' : 'unknown';
  }
  return 'unknown';
}

function translate(inputs) {
  if (!Array.isArray(inputs)) {
    throw new TypeError('translate expects an array of controller records');
  }
  const actions = [];
  let previousButton = null;
  for (const raw of inputs) {
    const record = normalizeRecord(raw);
    if (record.button === previousButton) {
      actions.push('hold');
    } else {
      actions.push(actionFor(record.button, record.state));
    }
    previousButton = record.button;
  }
  return actions;
}

function report(inputs) {
  const actions = translate(inputs);
  const lines = actions.map(function (action, index) {
    const record = normalizeRecord(inputs[index]);
    const note = action === 'unknown' ? ' (no mapping)' : '';
    return record.button + ' while ' + record.state + ' -> ' + action + note;
  });
  const mashes = actions.filter(function (action) {
    return action === 'hold';
  }).length;
  if (mashes !== 0) {
    lines.push('suppressed ' + mashes + ' repeated press(es)');
  }
  return lines.join('\n');
}

const session = [
  { button: 'cross', state: 'grounded' },
  { button: 'cross', state: 'airborne' },
  { button: 'circle', state: 'moving' },
  { button: 'square', state: 'defending' },
  { button: 'triangle', state: 'idle' },
  { button: 'triangle', state: 'moving' }
];

console.log(report(session));
console.log(translate(session).join(', '));

