const PRICES = [
  { name: 'vanilla', size: 'single', price: 2.0 },
  { name: 'vanilla', size: 'double', price: 3.0 },
  { name: 'chocolate', size: 'single', price: 2.5 },
  { name: 'sprinkles', size: 'regular', price: 0.5 },
  { name: 'fudge', size: 'extra', price: 1.2 }
];

function normalize(record) {
  if (typeof record !== 'object') {
    throw new TypeError('each ingredient must be a record with name and size');
  }
  if (record === null) {
    throw new TypeError('each ingredient must be a record with name and size');
  }
  const name = String(record.name).trim().toLowerCase();
  const size = String(record.size).trim().toLowerCase();
  if (name === '') {
    throw new Error('ingredient name must not be empty');
  }
  if (size === '') {
    throw new Error('ingredient size must not be empty');
  }
  return { name, size };
}

function priceOf(name, size) {
  for (const entry of PRICES) {
    if (entry.name !== name) {
      continue;
    }
    if (entry.size === size) {
      return entry.price;
    }
  }
  return 0;
}

function build(ingredients) {
  if (!Array.isArray(ingredients)) {
    throw new TypeError('ingredients must be an array');
  }
  let total = 0;
  let previousName = null;
  for (const record of ingredients) {
    const { name, size } = normalize(record);
    let price = priceOf(name, size);
    if (name === previousName) {
      price *= 0.8;
    }
    total += price;
    previousName = name;
  }
  return Math.round(total * 100) / 100;
}

function describe(ingredients) {
  const lines = [];
  let previousName = null;
  for (const record of ingredients) {
    const { name, size } = normalize(record);
    const base = priceOf(name, size);
    const repeat = name === previousName;
    const price = repeat ? base * 0.8 : base;
    let note = '';
