const COLORS = ['red', 'blue', 'green', 'yellow'];

function normalizeColor(color) {
  if (typeof color !== 'string') {
    throw new TypeError('color must be a string');
  }
  const cleaned = color.trim().toLowerCase();
  if (COLORS.indexOf(cleaned) === -1) {
    throw new RangeError('unknown color: ' + color);
  }
  return cleaned;
}

function normalizePosition(position) {
  const value = typeof position === 'string' ? Number(position) : position;
  if (Number.isInteger(value) !== true) {
    throw new TypeError('position must be an integer');
  }
  if (value < 1 || value > 4) {
    throw new RangeError('position out of range: ' + position);
  }
  return value;
}

function parseGuess(record) {
  if (typeof record === 'string') {
    const parts = record.trim().split(/\s+/);
    if (parts.length !== 2) {
      throw new SyntaxError('cannot parse guess: ' + record);
    }
    return { color: normalizeColor(parts[0]), position: normalizePosition(parts[1]) };
  }
  return { color: normalizeColor(record.color), position: normalizePosition(record.position) };
}

function pegFor(color, position) {
  if (color === 'red') {
    if (position === 1) return 'black';
    return position === 3 ? 'white' : 'none';
  }
  if (color === 'blue') {
    if (position === 2) return 'black';
    return position === 4 ? 'white' : 'none';
  }
  if (color === 'green') {
    return position === 3 ? 'black' : 'none';
  }
  return position === 4 ? 'black' : 'none';
}

function evaluate(guesses) {
  const result = { black: 0, white: 0 };
  guesses.forEach(function (record) {
    const guess = parseGuess(record);
    const peg = pegFor(guess.color, guess.position);
    if (peg === 'black') {
      result.black += 1;
    } else if (peg === 'white') {
      result.white += 1;
    }
  });
  return result;
}

function formatReport(result) {
  const blackLabel = result.black === 1 ? 'black peg' : 'black pegs';
  const whiteLabel = result.white === 1 ? 'white peg' : 'white pegs';
  return result.black + ' ' + blackLabel + ', ' + result.white + ' ' + whiteLabel;
}

function main() {
  const rounds = [
    ['red 1', 'blue 4'],
    ['red 1', 'blue 2', 'green 3', 'yellow 4'],
    [{ color: 'Red', position: 3 }, { color: 'green', position: 1 }]
  ];
  rounds.forEach(function (guesses, index) {
    console.log('round ' + (index + 1) + ': ' + formatReport(evaluate(guesses)));
  });
}

main();

module.exports = { evaluate, parseGuess, pegFor, formatReport };

