function normalizeInput(value) {
  if (typeof value === 'boolean') {
    return value;
  }
  if (typeof value === 'number') {
    return value === 1;
  }
  if (typeof value === 'string') {
    const text = value.trim().toLowerCase();
    if (text === 'true') {
      return true;
    }
    if (text === '1') {
      return true;
    }
    if (text === 'false') {
      return false;
    }
    if (text === '0') {
      return false;
    }
    throw new Error('unrecognised logic level: ' + value);
  }
  throw new Error('unsupported input type: ' + typeof value);
}

function evaluateGate(operation, a, b) {
  const op = String(operation).trim().toLowerCase();
  if (op === 'and') {
    if (a !== true) {
      return false;
    }
    return b === true;
  }
  if (op === 'or') {
    if (a === true) {
      return true;
    }
    return b === true;
  }
  if (op === 'xor') {
    return a !== b;
  }
  if (op === 'nand') {
    if (a !== true) {
      return true;
    }
    return b !== true;
  }
  if (op === 'nor') {
    if (a === false) {
      return b === false;
    }
    return false;
  }
  throw new Error('unknown operation: ' + operation);
}

function simulate(gates) {
  if (Array.isArray(gates) !== true) {
    throw new Error('simulate expects an array of gate records');
  }
  return gates.map(function (gate) {
    const one = normalizeInput(gate.inputOne);
    const two = normalizeInput(gate.inputTwo);
    return evaluateGate(gate.operation, one, two);
  });
}

function report(gates, results) {
  const lines = [];
  for (let i = 0; i < gates.length; i += 1) {
    const gate = gates[i];
    const label = String(gate.operation).trim().toLowerCase();
    const level = results[i] === true ? 'HIGH' : 'LOW';
    lines.push(label + '(' + gate.inputOne + ', ' + gate.inputTwo + ') -> ' + level);
  }
  return lines.join('\n');
}

const circuit = [
  { operation: 'and', inputOne: true, inputTwo: true },
  { operation: 'or', inputOne: false, inputTwo: true },
  { operation: 'xor', inputOne: true, inputTwo: true },
  { operation: 'nand', inputOne: 'true', inputTwo: 1 },
  { operation: 'nor', inputOne: 'false', inputTwo: 0 }
];

const outputs = simulate(circuit);
console.log(report(circuit, outputs));
console.log('high count: ' + outputs.filter(function (r) { return r === true; }).length);

