function normalizeField(value, fieldName) {
  if (typeof value !== 'string') {
    throw new TypeError(fieldName + ' must be a string');
  }
  return value.trim().toLowerCase();
}

function parseRecord(record, index) {
  if (typeof record !== 'object') {
    throw new TypeError('record ' + index + ' must be an object');
  }
  if (record === null) {
    throw new TypeError('record ' + index + ' must not be null');
  }
  return {
    target: normalizeField(record.target, 'target'),
    mount: normalizeField(record.mount, 'mount'),
    seeing: normalizeField(record.seeing, 'seeing')
  };
}

function magnificationFor(entry) {
  if (entry.target === 'lunar') {
    if (entry.mount === 'tracking') {
      return 'low';
    }
  }
  if (entry.target === 'planetary') {
    if (entry.seeing === 'excellent') {
      return 'high';
    }
  }
  if (entry.target === 'deep space') {
    if (entry.seeing === 'average') {
      return 'maximum';
    }
  }
  if (entry.target === 'solar') {
    if (entry.mount === 'fixed') {
      return 'minimum';
    }
  }
  if (entry.target === 'terrestrial') {
    if (entry.seeing === 'poor') {
      return 'low';
    }
  }
  return 'unset';
}

function calibrate(targets) {
  if (!Array.isArray(targets)) {
    throw new TypeError('targets must be an array');
  }
  const levels = [];
  for (let i = 0; i < targets.length; i += 1) {
    levels.push(magnificationFor(parseRecord(targets[i], i)));
  }
  return levels;
}

function summarize(levels) {
  const counts = new Map();
  for (const level of levels) {
    const seen = counts.get(level);
    counts.set(level, seen === undefined ? 1 : seen + 1);
  }
  const parts = [];
  for (const [level, count] of counts) {
    parts.push(level + '=' + count);
  }
  return parts.length === 0 ? 'no observations' : parts.join(', ');
}

const observations = [
  { target: 'Lunar', mount: 'tracking', seeing: 'good' },
  { target: 'planetary', mount: 'tracking', seeing: 'excellent' },
  { target: 'deep space', mount: 'tracking', seeing: 'average' },
