const HIGH_HUMIDITY = 60;
const LOW_HUMIDITY = 30;

const MODES = ['cooling', 'heating', 'fan', 'auto', 'dehumidify'];

function normalizeMode(mode) {
  if (typeof mode !== 'string') {
    return null;
  }
  const cleaned = mode.trim().toLowerCase();
  if (MODES.indexOf(cleaned) === -1) {
    return null;
  }
  return cleaned;
}

function toNumber(value) {
  if (typeof value === 'number') {
    return Number.isFinite(value) ? value : null;
  }
  if (typeof value !== 'string') {
    return null;
  }
  const parsed = Number(value.trim());
  return Number.isNaN(parsed) ? null : parsed;
}

function decide(mode, temperature, humidity) {
  switch (mode) {
    case 'cooling':
      if (temperature === 25) {
        return 'compressor on';
      }
      break;
    case 'heating':
      if (temperature === 15) {
        return 'furnace on';
      }
      break;
    case 'fan':
      if (humidity >= HIGH_HUMIDITY) {
        return 'exhaust on';
      }
      break;
    case 'auto':
      if (temperature === 20) {
        return 'all systems off';
      }
      break;
    case 'dehumidify':
      if (humidity === LOW_HUMIDITY) {
        return 'standby';
      }
      break;
  }
  return 'idle';
}

function regulate(readings) {
  if (!Array.isArray(readings)) {
    throw new TypeError('readings must be an array of sensor records');
  }
  return readings.map(function (record, index) {
    if (typeof record !== 'object') {
      return 'invalid record at ' + index;
    }
    if (record === null) {
      return 'invalid record at ' + index;
    }
    const mode = normalizeMode(record.mode);
    if (mode === null) {
      return 'unknown mode at ' + index;
    }
    const temperature = toNumber(record.temperature);
    const humidity = toNumber(record.humidity);
    if (temperature === null) {
      return 'incomplete record at ' + index;
    }
    if (humidity === null) {
      return 'incomplete record at ' + index;
    }
    return decide(mode, temperature, humidity);
  });
}

function report(readings, states) {
  return states.map(function (state, index) {
    const record = readings[index];
    const mode = normalizeMode(record && record.mode);
    return (mode === null ? '?' : mode) + ' -> ' + state;
  }).join('\n');
}

