const SEASONS = ["summer", "winter", "spring", "autumn"];
const WEATHERS = ["clear", "snow", "rain"];
const DAYS = ["weekday", "weekend"];

function validateRequest(request, index) {
  if (Array.isArray(request) !== true) {
    throw new TypeError(`request ${index} is not an array`);
  }
  if (request.length !== 3) {
    throw new RangeError(`request ${index} must have exactly three elements`);
  }
  const [season, weather, day] = request;
  if (SEASONS.indexOf(season) === -1) {
    throw new RangeError(`request ${index} has unknown season "${season}"`);
  }
  if (WEATHERS.indexOf(weather) === -1) {
    throw new RangeError(`request ${index} has unknown weather "${weather}"`);
  }
  if (DAYS.indexOf(day) === -1) {
    throw new RangeError(`request ${index} has unknown day "${day}"`);
  }
}

function requestPrice(season, weather, day) {
  if (season === "summer") {
    return day === "weekend" ? 50 : 40;
  }
  if (season === "winter") {
    if (weather === "snow") {
      return 30;
    }
    return weather === "clear" ? 20 : 0;
  }
  if (season === "spring") {
    return day === "weekend" ? 35 : 25;
  }
  if (weather === "rain") {
    return 15;
  }
  return weather === "clear" ? 25 : 0;
}

function price(requests) {
  let total = 0;
  for (let i = 0; i < requests.length; i += 1) {
    const request = requests[i];
    validateRequest(request, i);
    total += requestPrice(request[0], request[1], request[2]);
  }
  return total;
}

function countBySeason(requests) {
  const counts = {};
  for (const request of requests) {
    const season = request[0];
    counts[season] = counts[season] === undefined ? 1 : counts[season] + 1;
  }
  return counts;
}

function report(requests) {
  const counts = countBySeason(requests);
  const lines = [];
  for (const season of SEASONS) {
    const visits = counts[season];
    if (visits === undefined) {
      continue;
    }
    const noun = visits === 1 ? "visit" : "visits";
    lines.push(`${season}: ${visits} ${noun}`);
  }
  if (lines.length === 0) {
    lines.push("no visits recorded");
  }
  lines.push(`total: $${price(requests)}`);
  return lines.join("\n");
}

const sample = [
  ["summer", "clear", "weekend"],
  ["winter", "snow", "weekday"],
  ["autumn", "rain", "weekend"],
  ["spring", "clear", "weekday"]
];

console.log(report(sample));
console.log(price([["summer", "clear", "weekend"], ["winter", "snow", "weekday"]]));

