const TIERS = ['platinum', 'gold', 'silver', 'bronze'];
const TIMES = ['morning', 'afternoon', 'evening'];
const PAYMENTS = ['current', 'overdue'];

function normalizeField(value) {
  if (typeof value !== 'string') {
    throw new TypeError('each entry field must be a string');
  }
  return value.trim().toLowerCase();
}

function normalizeEntry(entry) {
  if (!Array.isArray(entry) || entry.length !== 3) {
    throw new TypeError('each member entry must be a three-element array');
  }
  const tier = normalizeField(entry[0]);
  const time = normalizeField(entry[1]);
  const payment = normalizeField(entry[2]);
  if (TIERS.indexOf(tier) === -1) {
    throw new RangeError('unknown tier: ' + tier);
  }
  if (TIMES.indexOf(time) === -1) {
    throw new RangeError('unknown time: ' + time);
  }
  if (PAYMENTS.indexOf(payment) === -1) {
    throw new RangeError('unknown payment status: ' + payment);
  }
  return { tier: tier, time: time, payment: payment };
}

function accessFor(member) {
  if (member.payment === 'overdue') {
    return member.tier === 'platinum' ? 1 : 0;
  }
  if (member.tier === 'platinum') {
    return 1;
  }
  if (member.tier === 'gold') {
    if (member.time === 'morning') {
      return 1;
    }
    return member.time === 'evening' ? 1 : 0;
  }
  if (member.tier === 'silver') {
    return member.time === 'morning' ? 1 : 0;
  }
  if (member.tier === 'bronze') {
    return member.time === 'afternoon' ? 1 : 0;
  }
  return 0;
}

function scan(members) {
  if (!Array.isArray(members)) {
    throw new TypeError('members must be a list of entries');
  }
  let granted = 0;
  for (const entry of members) {
    granted += accessFor(normalizeEntry(entry));
  }
  return granted;
}

function report(members) {
  const lines = members.map(function (entry) {
    const member = normalizeEntry(entry);
    const verdict = accessFor(member) === 1 ? 'ADMIT' : 'DENY';
    return member.tier + '/' + member.time + '/' + member.payment + ': ' + verdict;
  });
  const granted = scan(members);
  const noun = granted === 1 ? 'pass' : 'passes';
  lines.push('total: ' + granted + ' ' + noun);
  return lines.join('\n');
}

