const PERIODS = ['peak', 'offpeak'];

function validateEntry(entry, index) {
  if (Array.isArray(entry) == false) {
    throw new TypeError('Entry ' + index + ' must be an array');
  }
  if (entry.length != 3) {
    throw new RangeError('Entry ' + index + ' must have exactly three elements');
  }
  const [type, time, hasPass] = entry;
  if (VEHICLE_TYPES.indexOf(type) == -1) {
    throw new RangeError('Entry ' + index + ' has unknown vehicle type: ' + type);
  }
  if (PERIODS.indexOf(time) == -1) {
    throw new RangeError('Entry ' + index + ' has unknown period: ' + time);
  }
  if (typeof hasPass != 'boolean') {
    throw new TypeError('Entry ' + index + ' must carry a boolean pass flag');
  }
  return { type: type, time: time, hasPass: hasPass };
}

function tollFor(type, time, hasPass) {
  if (hasPass == false) {
    if (type == 'car') {
      return time == 'peak' ? 5 : 3;
    }
    if (type == 'truck') {
      return time == 'peak' ? 10 : 7;
    }
    if (type == 'motorcycle') {
      return 2;
    }
  }
  if (type == 'bus') {
    if (time == 'peak') {
      return 8;
    }
  }
  if (type == 'truck') {
    return 2;
  }
  return 0;
}

function collect(vehicles) {
  if (Array.isArray(vehicles) == false) {
    throw new TypeError('collect expects a list of vehicle records');
  }
  let total = 0;
  for (let i = 0; i < vehicles.length; i += 1) {
