function parseCow(cow, index) {
  if (!Array.isArray(cow)) {
    throw new TypeError(`cow at index ${index} must be an array`);
  }
  if (cow.length !== 3) {
    throw new TypeError(`cow at index ${index} must have exactly three elements`);
  }
  const [breed, diet, morning] = cow;
  if (typeof breed !== 'string') {
    throw new TypeError(`breed at index ${index} must be a string`);
  }
  if (typeof diet !== 'string') {
    throw new TypeError(`diet at index ${index} must be a string`);
  }
  if (typeof morning !== 'boolean') {
    throw new TypeError(`morning flag at index ${index} must be a boolean`);
  }
  return {
    breed: breed.trim().toLowerCase(),
    diet: diet.trim().toLowerCase(),
    morning,
  };
}

function litersFor(cow) {
  const { breed, diet, morning } = cow;
  if (breed === 'holstein') {
    if (diet === 'grass' && morning) return 20;
    if (diet === 'grain') return 25;
  } else if (breed === 'jersey') {
    if (diet === 'grass' && !morning) return 15;
    if (diet === 'grain' && morning) return 18;
  } else if (breed === 'guernsey') {
    if (diet === 'grass') return 16;
    if (diet === 'grain' && !morning) return 14;
  } else if (breed === 'ayrshire') {
    return morning ? 19 : 13;
  }
  return 0;
}

function milk(cows) {
  let totalLiters = 0;
  cows.forEach((cow, index) => {
    totalLiters += litersFor(parseCow(cow, index));
  });
  return totalLiters;
}

function summarizeByBreed(cows) {
  const totals = new Map();
  cows.forEach((cow, index) => {
    const parsed = parseCow(cow, index);
    const previous = totals.get(parsed.breed);
    const running = previous === undefined ? 0 : previous;
    totals.set(parsed.breed, running + litersFor(parsed));
  });
  return [...totals.entries()].sort((a, b) => a[0].localeCompare(b[0]));
}

function formatReport(cows) {
  const lines = cows.map((cow, index) => {
    const parsed = parseCow(cow, index);
    const liters = litersFor(parsed);
    const shift = parsed.morning ? 'morning' : 'evening';
    const note = liters === 0 ? ' (no yield)' : '';
    return `${parsed.breed}/${parsed.diet}/${shift}: ${liters} L${note}`;
  });
  summarizeByBreed(cows).forEach(([breed, liters]) => {
    lines.push(`subtotal ${breed}: ${liters} L`);
  });
  lines.push(`total: ${milk(cows)} L`);
  return lines.join('\n');
}

function main() {
  const herd = [
    ['holstein', 'grass', true],
    ['jersey', 'grain', true],
    ['ayrshire', 'none', false],
  ];
  console.log(formatReport(herd));
  console.log(milk(herd));
}

main();

