function validateSheep(entry, index) {
  if (Array.isArray(entry) !== true) {
    throw new TypeError("sheep " + index + " is not a three-element array");
  }
  if (entry.length !== 3) {
    throw new TypeError("sheep " + index + " must have breed, season and washed");
  }
  const [breed, season, washed] = entry;
  if (typeof breed !== "string") {
    throw new TypeError("sheep " + index + " has a non-string breed");
  }
  if (typeof season !== "string") {
    throw new TypeError("sheep " + index + " has a non-string season");
  }
  if (typeof washed !== "boolean") {
    throw new TypeError("sheep " + index + " has a non-boolean washed flag");
  }
  return [breed.trim().toLowerCase(), season.trim().toLowerCase(), washed];
}

function yieldFor(breed, season, washed) {
  if (breed === "merino") {
    if (season === "spring" && washed) return 10;
    if (season === "autumn") return 8;
    return 0;
  }
  if (breed === "dorset") {
    if (season === "spring") return 6;
    if (washed) return 0;
    return season === "summer" ? 5 : 0;
  }
  if (breed === "suffolk") {
    if (season === "autumn" && washed) return 7;
    if (season === "spring") return 9;
    return 0;
  }
  if (breed === "cheviot") {
    return washed ? 6 : 4;
  }
  return 0;
}

function shear(flock) {
  let totalWool = 0;
  flock.forEach(function (entry, index) {
    const [breed, season, washed] = validateSheep(entry, index);
    totalWool += yieldFor(breed, season, washed);
  });
  return totalWool;
}

function summarize(flock) {
  const perBreed = new Map();
  flock.forEach(function (entry, index) {
    const [breed, season, washed] = validateSheep(entry, index);
    if (perBreed.has(breed) === false) {
      perBreed.set(breed, { breed: breed, count: 0, wool: 0 });
    }
    const record = perBreed.get(breed);
    record.count += 1;
    record.wool += yieldFor(breed, season, washed);
  });
  return Array.from(perBreed.values()).sort(function (a, b) {
    if (a.wool !== b.wool) return b.wool - a.wool;
    return a.breed < b.breed ? -1 : 1;
  });
}

function formatReport(flock) {
  const rows = summarize(flock);
  if (rows.length === 0) return "empty flock: 0 wool";
  const lines = rows.map(function (row) {
    return row.breed + " x" + row.count + ": " + row.wool + " wool";
  });
  lines.push("total: " + shear(flock) + " wool");
  return lines.join("\n");
}

const sample = [["merino", "spring", true], ["suffolk", "autumn", true], ["cheviot", "winter", false]];
const mixed = [["dorset", "summer", false], ["dorset", "spring", true], ["merino", "autumn", false]];

console.log(shear(sample));
console.log(formatReport(sample));
console.log(formatReport(mixed));

module.exports = { shear: shear, yieldFor: yieldFor, summarize: summarize, formatReport: formatReport };

