'use strict';

function normalizeCat(cat, index) {
  if (!Array.isArray(cat) || cat.length !== 3) {
    throw new TypeError(`cat #${index} must be an array of [breed, pattern, calm]`);
  }
  const [breed, pattern, calm] = cat;
  if (typeof breed !== 'string') {
    throw new TypeError(`cat #${index}: breed must be a string`);
  }
  if (typeof pattern !== 'string') {
    throw new TypeError(`cat #${index}: pattern must be a string`);
  }
  if (typeof calm !== 'boolean') {
    throw new TypeError(`cat #${index}: calm must be a boolean`);
  }
  return { breed: breed.trim().toLowerCase(), pattern: pattern.trim().toLowerCase(), calm };
}

function scoreCat(breed, pattern, calm) {
  switch (breed) {
    case 'persian':
      if (pattern === 'solid' && calm) return 90;
      if (pattern === 'tabby') return 70;
      return 0;
    case 'siamese':
      if (pattern === 'point' && !calm) return 60;
      if (pattern === 'solid' && calm) return 80;
      return 0;
    case 'maine':
      if (pattern === 'tabby' && calm) return 95;
      if (pattern === 'solid') return 85;
      return 0;
    case 'ragdoll':
      return calm ? 99 : 50;
    default:
      return 0;
  }
}

function tally(cats) {
  if (!Array.isArray(cats)) {
    throw new TypeError('cats must be an array');
  }
  return cats.map((cat, index) => {
    const entry = normalizeCat(cat, index);
    entry.points = scoreCat(entry.breed, entry.pattern, entry.calm);
    return entry;
  });
}

function score(cats) {
  return tally(cats).reduce((total, entry) => total + entry.points, 0);
}

function bestCats(rows) {
  const top = rows.reduce((max, entry) => (entry.points > max ? entry.points : max), 0);
  return rows.filter((entry) => entry.points === top);
}

function formatReport(cats) {
  const rows = tally(cats);
  const lines = rows.map((entry) => {
    const mood = entry.calm ? 'calm' : 'lively';
    return `${entry.breed}/${entry.pattern} (${mood}): ${entry.points} pts`;
  });
  const unscored = rows.filter((entry) => entry.points === 0).length;
  if (unscored === 1) {
    lines.push('1 cat earned no points.');
  } else if (unscored !== 0) {
    lines.push(`${unscored} cats earned no points.`);
  }
  const winners = bestCats(rows);
  if (winners.length === 1) {
    lines.push(`Top cat: ${winners[0].breed} with ${winners[0].points} pts.`);
  } else if (winners.length > 1) {
    lines.push(`Tie at ${winners[0].points} pts: ${winners.map((e) => e.breed).join(', ')}.`);
  }
  lines.push(`Total points: ${rows.reduce((total, entry) => total + entry.points, 0)}`);
  return lines.join('\n');
}

function main() {
  const show = [['persian', 'solid', true], ['siamese', 'point', false], ['ragdoll', 'none', true]];
  console.log(formatReport(show));
  console.log(score(show));
}

main();

module.exports = { score, scoreCat, tally, bestCats, formatReport };

