const NOTE_BY_RECIPE = ['floral', 'sweet', 'base'];

function normalizeIngredient(entry, index) {
  if (Array.isArray(entry) !== true) {
    throw new TypeError('Ingredient ' + index + ' must be an array');
  }
  if (entry.length !== 3) {
    throw new TypeError('Ingredient ' + index + ' must have essence, drops, temperature');
  }
  const [essence, drops, temperature] = entry;
  if (typeof essence !== 'string') {
    throw new TypeError('Ingredient ' + index + ' has a non-string essence');
  }
  if (typeof temperature !== 'string') {
    throw new TypeError('Ingredient ' + index + ' has a non-string temperature');
  }
  if (Number.isFinite(drops) !== true) {
    throw new TypeError('Ingredient ' + index + ' has a non-numeric drop count');
  }
  return {
    essence: essence.trim().toLowerCase(),
    drops: drops,
    temperature: temperature.trim().toLowerCase()
  };
}

function noteFor(essence, temperature) {
  if (essence === 'rose') {
    if (temperature === 'cold') return 'floral';
    if (temperature === 'hot') return 'sweet';
    return null;
  }
  if (essence === 'jasmine') {
    return temperature === 'cold' ? 'base' : null;
  }
  if (essence === 'vanilla') {
    return temperature === 'warm' ? 'sweet' : null;
  }
  if (essence === 'musk') {
    return temperature === 'ambient' ? 'base' : null;
  }
  return null;
}

function processVat(ingredients) {
  const notes = { floral: 0, sweet: 0, base: 0 };
  for (let i = 0; i < ingredients.length; i += 1) {
    const item = normalizeIngredient(ingredients[i], i);
    const note = noteFor(item.essence, item.temperature);
    if (note !== null) {
      notes[note] += item.drops;
    }
    if (notes.floral === 10) {
      if (notes.sweet === 5) return 'signature scent';
    }
  }
  return NOTE_BY_RECIPE.reduce((sum, key) => sum + notes[key], 0);
}

function describeBatch(label, ingredients) {
  const outcome = processVat(ingredients);
  if (outcome === 'signature scent') {
    return label + ': signature scent achieved';
  }
  return label + ': ' + outcome + ' drops blended';
}

function main() {
  console.log(describeBatch('single rose', [['rose', 10, 'cold']]));
  console.log(describeBatch('balanced', [['rose', 10, 'cold'], ['vanilla', 5, 'warm']]));
  console.log(describeBatch('mixed', [['jasmine', 3, 'cold'], ['musk', 4, 'ambient'], ['rose', 2, 'hot']]));
  console.log(describeBatch('rejected', [['rose', 6, 'warm'], ['lilac', 9, 'cold']]));
}

main();

