function validateStage(stage, index) {
  if (Array.isArray(stage) !== true) {
    throw new TypeError('Stage ' + index + ' must be an array of [process, valve]');
  }
  if (stage.length !== 2) {
    throw new TypeError('Stage ' + index + ' must have exactly two entries');
  }
  const [process, valve] = stage;
  if (typeof process !== 'string') {
    throw new TypeError('Stage ' + index + ' process must be a string');
  }
  if (typeof valve !== 'string') {
    throw new TypeError('Stage ' + index + ' valve must be a string');
  }
  return [process, valve];
}

function reduction(process, valve) {
  if (process === 'screen') {
    return valve === 'open' ? 10 : 0;
  }
  if (process === 'coagulate') {
    return valve === 'open' ? 20 : 0;
  }
  if (process === 'filter') {
    return valve === 'active' ? 25 : 0;
  }
  if (process === 'disinfect') {
    return valve === 'active' ? 10 : 0;
  }
  return 0;
}

function treatWater(stages) {
  const results = [];
  let contamination = 100;

  stages.forEach(function (stage, index) {
    const [process, valve] = validateStage(stage, index);

    if (process === 'test') {
      if (contamination === 0) {
        results.push('Test passed: water is clean');
      } else {
        results.push('Test failed: contamination at ' + contamination);
      }
      return;
    }

    contamination -= reduction(process, valve);
  });

  return results;
}

function summarize(results) {
  if (results.length === 0) {
    return 'No tests were run.';
  }
  const passes = results.filter(function (line) {
    return line.startsWith('Test passed');
  }).length;
  const verdict = passes === results.length ? 'all clear' : 'attention required';
  return passes + '/' + results.length + ' tests passed (' + verdict + ')';
}

const fullRun = [
  ['screen', 'open'],
  ['coagulate', 'open'],
  ['filter', 'active'],
  ['disinfect', 'active'],
  ['test', 'open'],
  ['filter', 'closed'],
  ['test', 'open']
];

const shortRun = [['screen', 'open'], ['test', 'open']];

[shortRun, fullRun].forEach(function (run) {
  const results = treatWater(run);
  results.forEach(function (line) {
    console.log(line);
  });
  console.log(summarize(results));
});

