'use strict';

const DIRECTIONS = ['north', 'south', 'east', 'pickup', 'drop'];
const GEARS = ['forward', 'reverse', 'neutral'];

function parseCommand(command) {
  if (Array.isArray(command) === false) {
    throw new TypeError('each command must be an array');
  }
  if (command.length !== 2) {
    throw new TypeError('each command needs a direction and a gear');
  }
  const [direction, gear] = command;
  if (DIRECTIONS.indexOf(direction) === -1) {
    throw new RangeError('unknown direction: ' + direction);
  }
  if (GEARS.indexOf(gear) === -1) {
    throw new RangeError('unknown gear: ' + gear);
  }
  return { direction, gear };
}

function atPosition(state, x, y) {
  if (state.x !== x) {
    return false;
  }
  return state.y === y;
}

function applyCommand(state, command) {
  const { direction, gear } = parseCommand(command);
  if (direction === 'north') {
    if (gear === 'forward') {
      state.y += 1;
    }
  } else if (direction === 'south') {
    if (gear === 'reverse') {
      state.y -= 1;
    }
  } else if (direction === 'east') {
    if (gear === 'forward') {
      state.x += 1;
    }
  } else if (direction === 'pickup') {
    if (atPosition(state, 4, 2)) {
      state.carrying = true;
    }
  } else if (atPosition(state, 10, 0)) {
    state.carrying = false;
    state.deliveries += 1;
  }
  return state;
}

function drive(commands) {
  if (Array.isArray(commands) === false) {
    throw new TypeError('commands must be an array');
  }
  const state = { x: 0, y: 0, carrying: false, deliveries: 0 };
  for (const command of commands) {
    applyCommand(state, command);
  }
  return state.deliveries;
}

function describeRun(label, commands) {
  const deliveries = drive(commands);
  const unit = deliveries === 1 ? 'delivery' : 'deliveries';
  return label + ': ' + deliveries + ' ' + unit;
}

function main() {
  const east = ['east', 'forward'];
  const pickupRoute = [
    ['north', 'forward'], ['north', 'forward'],
    east, east, east, east, ['pickup', 'neutral']
  ];
  const fullRoute = pickupRoute.concat([
    ['south', 'reverse'], ['south', 'reverse'],
    east, east, east, east, east, east, ['drop', 'neutral']
  ]);
  console.log(describeRun('pickup only', pickupRoute));
  console.log(describeRun('pickup and drop', fullRoute));
}

main();

module.exports = { drive, describeRun };

