'use strict';

const DEFAULTS = { ph: 7, ec: 1, volume: 0 };

function normalizeType(type) {
  return String(type).trim().toLowerCase().replace(/[\s_-]+/g, ' ');
}

function isValidSensor(sensor) {
  if (sensor === null) {
    return false;
  }
  if (typeof sensor !== 'object') {
    return false;
  }
  if (typeof sensor.mode !== 'string') {
    return false;
  }
  return normalizeType(sensor.type) !== '';
}

function round2(value) {
  return Math.round(value * 100) / 100;
}

function simulate(sensors) {
  const state = { ph: DEFAULTS.ph, ec: DEFAULTS.ec, volume: DEFAULTS.volume, cooling: false };
  const readings = Array.isArray(sensors) ? sensors : [];
  for (const sensor of readings) {
    if (!isValidSensor(sensor)) {
      continue;
    }
    const type = normalizeType(sensor.type);
    const mode = sensor.mode.trim().toLowerCase();
    if (type === 'ph low') {
      if (mode === 'auto') {
        state.ph = round2(state.ph + 0.1);
      }
    } else if (type === 'ph high') {
      if (mode === 'auto') {
        state.ph = round2(state.ph - 0.1);
      }
    } else if (type === 'ec low') {
      if (mode === 'auto') {
        state.ec = round2(state.ec + 0.2);
      }
    } else if (type === 'water level') {
      if (mode === 'manual') {
        state.volume += 1;
      }
    } else if (type === 'temperature') {
      if (mode === 'auto') {
        state.cooling = true;
      }
    } else if (type === 'flush') {
      if (mode === 'override') {
        state.ph = 7;
        state.ec = 1;
      }
    }
  }
  return state;
}

function dose(sensors) {
  const state = simulate(sensors);
  return [state.ph, state.ec];
}

function formatLine(sensor) {
  if (!isValidSensor(sensor)) {
    return 'invalid sensor entry';
  }
  const value = typeof sensor.value === 'number' ? sensor.value.toFixed(2) : 'n/a';
  return `${normalizeType(sensor.type)} [${sensor.mode.trim().toLowerCase()}] = ${value}`;
}

function formatReport(sensors) {
  const readings = Array.isArray(sensors) ? sensors : [];
  const lines = readings.map(formatLine);
  if (lines.length === 0) {
    lines.push('no sensor readings');
  }
  const state = simulate(readings);
  lines.push(`ph=${state.ph.toFixed(2)} ec=${state.ec.toFixed(2)}`);
  lines.push(`volume=${state.volume} cooling=${state.cooling ? 'on' : 'off'}`);
  return lines.join('\n');
}

function main() {
  const batches = [
    [{ type: 'ph low', value: 6.4, mode: 'auto' }],
    [
      { type: 'ec low', value: 0.8, mode: 'auto' },
      { type: 'water level', value: 12, mode: 'manual' },
      { type: 'temperature', value: 27.5, mode: 'auto' },
      { type: 'ph high', value: 7.6, mode: 'manual' }
    ],
    [{ type: 'ph high', value: 7.9, mode: 'auto' }, { type: 'flush', value: 0, mode: 'override' }]
  ];
  for (const batch of batches) {
    console.log(formatReport(batch));
    console.log(`dose -> [${dose(batch).join(', ')}]\n`);
  }
}

main();

module.exports = { dose, simulate, formatReport, isValidSensor };

