function normalize(value) {
  return typeof value === 'string' ? value.trim().toLowerCase() : '';
}

function parseParcel(entry) {
  if (Array.isArray(entry) !== true) {
    return null;
  }
  if (entry.length !== 3) {
    return null;
  }
  const type = normalize(entry[0]);
  const size = normalize(entry[1]);
  const zone = normalize(entry[2]);
  if (type === '') {
    return null;
  }
  return { type: type, size: size, zone: zone };
}

function binIndexFor(parcel) {
  if (parcel.type === 'hazardous') {
    return -1;
  }
  if (parcel.type === 'letter') {
    if (parcel.size === 'standard') {
      return 0;
    }
    return parcel.size === 'large' ? 1 : -1;
  }
  if (parcel.type === 'package') {
    if (parcel.zone === 'local') {
      return 2;
    }
    return parcel.zone === 'national' ? 3 : -1;
  }
  if (parcel.type === 'international' && parcel.size === 'large') {
    return 4;
  }
  return -1;
}

function route(parcels) {
  const bins = [0, 0, 0, 0, 0];
  if (Array.isArray(parcels) !== true) {
    return bins;
  }
  for (const entry of parcels) {
    const parcel = parseParcel(entry);
    if (parcel === null) {
      continue;
    }
    const index = binIndexFor(parcel);
    if (index !== -1) {
      bins[index] += 1;
    }
  }
  return bins;
}

