function validateCar(car, index) {
  if (!Array.isArray(car)) {
    return 'car ' + index + ' is not an array';
  }
  if (car.length !== 2) {
    return 'car ' + index + ' must have a type and a cargo status';
  }
  if (typeof car[0] !== 'string') {
    return 'car ' + index + ' has a non-string type';
  }
  if (typeof car[1] !== 'string') {
    return 'car ' + index + ' has a non-string cargo status';
  }
  return null;
}

function capacityOf(type, cargo) {
  if (type === 'boxcar') {
    return cargo === 'full' ? 50 : 0;
  }
  if (type === 'flatcar') {
    return cargo === 'empty' ? 20 : 0;
  }
  return 0;
}

function assemble(cars) {
  if (!Array.isArray(cars) || cars.length === 0) {
    return [false, 0];
  }
  let capacity = 0;
  let valid = true;
  for (let i = 0; i < cars.length; i += 1) {
    const problem = validateCar(cars[i], i);
    if (problem !== null) {
      return [false, 0];
    }
    const type = cars[i][0];
    const cargo = cars[i][1];
    if (i === 0) {
      valid = valid && type === 'locomotive';
    }
    if (i === cars.length - 1) {
      valid = valid && type === 'caboose';
    }
    if (type === 'tanker' && i > 0) {
      const previousType = cars[i - 1][0];
      if (previousType === 'passenger') {
        valid = false;
      }
    }
    capacity += capacityOf(type, cargo);
  }
  return [valid, capacity];
}

function describe(name, cars) {
  const result = assemble(cars);
  const verdict = result[0] === true ? 'valid' : 'invalid';
  return name + ': ' + verdict + ', capacity ' + result[1];
}

function main() {
  const trains = [
    ['short freight', [['locomotive', 'empty'], ['boxcar', 'full'], ['caboose', 'empty']]],
    ['mixed load', [['locomotive', 'empty'], ['flatcar', 'empty'], ['boxcar', 'full'], ['caboose', 'empty']]],
    ['bad tanker', [['locomotive', 'empty'], ['passenger', 'full'], ['tanker', 'full'], ['caboose', 'empty']]],
    ['no caboose', [['locomotive', 'empty'], ['boxcar', 'full']]],
    ['malformed', [['locomotive', 'empty'], ['boxcar'], ['caboose', 'empty']]]
  ];
  for (const entry of trains) {
    console.log(describe(entry[0], entry[1]));
  }
}

main();

module.exports = { assemble, capacityOf, validateCar, describe };

