const ROAST_GAINS = { near: 1, close: 3, fire: 10 };

function parseAction(action) {
  if (!Array.isArray(action)) {
    throw new TypeError('Each action must be an array');
  }
  if (action.length !== 2) {
    throw new TypeError('Each action needs an action name and a distance');
  }
  const [name, distance] = action;
  if (typeof name !== 'string') {
    throw new TypeError('Action name must be a string');
  }
  if (typeof distance !== 'string') {
    throw new TypeError('Distance must be a string');
  }
  return { name, distance };
}

function applyAction(progress, name, distance) {
  if (name === 'hold') {
    const gain = ROAST_GAINS[distance];
    if (typeof gain === 'number') {
      progress.level += gain;
    }
  } else if (name === 'rotate') {
    if (distance === 'above') {
      progress.rotations += 1;
    }
  }
}

function stateForLevel(level) {
  if (level === 5) {
    return 'golden';
  }
  if (level === 10) {
    return 'burnt';
  }
  return null;
}

function cookDetailed(actions) {
  const progress = { level: 0, rotations: 0 };
  let state = 'raw';
  for (const action of actions) {
    const { name, distance } = parseAction(action);
    applyAction(progress, name, distance);
    const reached = stateForLevel(progress.level);
    if (reached !== null) {
      state = reached;
    }
  }
  return { state, level: progress.level, rotations: progress.rotations };
}

function cook(actions) {
  return cookDetailed(actions).state;
}

function formatReport(actions) {
  const result = cookDetailed(actions);
  let advice;
  if (result.state === 'golden') {
    advice = 'perfectly golden, eat it now';
  } else if (result.state === 'burnt') {
    advice = 'burnt to a crisp, start again';
  } else {
    advice = 'still raw, keep roasting';
  }
  const turns = result.rotations === 1 ? 'turn' : 'turns';
  return `roast ${result.level}, ${result.rotations} ${turns}: ${advice}`;
}

const sessions = [
  [['hold', 'near'], ['hold', 'near'], ['hold', 'near'], ['hold', 'near'], ['hold', 'near']],
  [['hold', 'close'], ['rotate', 'above'], ['hold', 'close'], ['rotate', 'above'], ['hold', 'fire']],
  [['rotate', 'above'], ['hold', 'far'], ['hold', 'close']],
  [['hold', 'fire']]
];

for (const session of sessions) {
  console.log(`${cook(session)} -> ${formatReport(session)}`);
}

module.exports = { cook, cookDetailed, formatReport };

