'use strict';

const VALID_INSTRUCTIONS = ['move x', 'move y', 'move z', 'extrude', 'home x', 'bed temp'];

function parseCommand(command) {
  if (Array.isArray(command) !== true) {
    throw new TypeError('each command must be an array');
  }
  if (command.length !== 3) {
    throw new TypeError('each command must have an instruction, a value and a mode');
  }
  const [instruction, value, mode] = command;
  if (typeof instruction !== 'string') {
    throw new TypeError('instruction must be a string');
  }
  if (typeof value !== 'number') {
    throw new TypeError('value must be a number');
  }
  if (Number.isFinite(value) === false) {
    throw new TypeError('value must be finite');
  }
  if (typeof mode !== 'string') {
    throw new TypeError('mode must be a string');
  }
  const name = instruction.trim().toLowerCase();
  if (VALID_INSTRUCTIONS.indexOf(name) === -1) {
    throw new Error('unknown instruction: ' + instruction);
  }
  return { name, value, mode: mode.trim().toLowerCase() };
}

function applyCommand(state, command) {
  const { name, value, mode } = parseCommand(command);
  if (name === 'move x') {
    if (mode === 'absolute') {
      state.x = value;
    } else if (mode === 'relative') {
      state.x += value;
    }
  } else if (name === 'move y') {
    if (mode === 'absolute') {
      state.y = value;
    } else if (mode === 'relative') {
      state.y += value;
    }
  } else if (name === 'move z') {
    if (mode === 'absolute') {
      state.z = value;
    } else if (mode === 'relative') {
      state.z += value;
    }
  } else if (name === 'extrude') {
    if (mode === 'absolute') {
      state.e = value;
    } else if (mode === 'relative') {
      state.e += value;
    }
  } else if (name === 'home x') {
    if (mode === 'all') {
      state.x = 0;
    }
  } else if (value === 0) {
    state.heater = false;
  } else {
    state.heater = true;
  }
  return state;
}

function print(commands) {
  if (Array.isArray(commands) !== true) {
    throw new TypeError('commands must be an array');
  }
  const state = { x: 0, y: 0, z: 0, e: 0, heater: true };
  for (const command of commands) {
    applyCommand(state, command);
  }
  return [state.x, state.y, state.z, state.e];
}

function formatReport(position) {
  const labels = ['X', 'Y', 'Z', 'E'];
  return position
    .map((coordinate, index) => labels[index] + '=' + coordinate.toFixed(2))
    .join(' ');
}

const job = [
  ['move x', 10, 'absolute'],
  ['move y', 5, 'relative'],
  ['move z', 0.3, 'absolute'],
  ['extrude', 2.5, 'absolute'],
  ['bed temp', 0, 'set'],
];

console.log(formatReport(print(job)));

module.exports = { print, applyCommand, parseCommand, formatReport };

