const BIN_LIMIT = 10;
const LABELS = ['bin one', 'bin two', 'bin three', 'bin four', 'compost'];

function normalize(item) {
  if (typeof item !== 'string') {
    return null;
  }
  return item.trim().toLowerCase();
}

function sort(items) {
  const counts = [0, 0, 0, 0, 0];
  for (const raw of items) {
    const item = normalize(raw);
    if (item === null) {
      continue;
    }
    if (item === '') {
      return counts;
    }
    if (item === 'plastic') {
      if (counts[0] < BIN_LIMIT) {
        counts[0] += 1;
      }
    } else if (item === 'glass') {
      if (counts[1] < BIN_LIMIT) {
        counts[1] += 1;
      }
    } else if (item === 'metal') {
      counts[2] += 1;
    } else if (item === 'paper') {
      counts[3] += 1;
    } else if (item === 'organic') {
      counts[4] += 1;
    } else if (item === 'hazardous') {
      return counts;
    }
  }
  return counts;
}

function isBinOpen(counts, index) {
  if (index === 4) {
    return true;
  }
  return counts[index] < BIN_LIMIT;
}

function report(counts) {
  const lines = counts.map(function (count, index) {
    const state = isBinOpen(counts, index) ? 'open' : 'full';
    const unit = count === 1 ? 'item' : 'items';
    return LABELS[index] + ': ' + count + ' ' + unit + ' (' + state + ')';
  });
  return lines.join('\n');
}

function main() {
  const load = ['plastic', 'glass', 'organic'];
  const counts = sort(load);
  console.log(report(counts));

  const mixed = ['paper', 42, 'unknown', 'metal', 'hazardous', 'paper'];
  const stopped = sort(mixed);
  console.log(report(stopped));
  if (stopped[3] === 1) {
    console.log('processing halted on hazardous material');
  }

  const overflow = new Array(12).fill('plastic').concat(['', 'metal']);
  const capped = sort(overflow);
  console.log(report(capped));
  if (capped[2] !== 0) {
    console.log('metal reached bin three after the empty marker');
  }
}

main();

