  }
  if (EVENT_NAMES.indexOf(name) === -1) {
    throw new Error(`unknown event: ${name}`);
  }
  return { name, degrees };
}

function roast(events) {
  let temperature = 0;
  let running = false;
  for (const entry of events) {
    const { name, degrees } = parseEvent(entry);
    if (NO_OP_EVENTS.includes(name)) {
      continue;
