function validateEntry(entry) {
  if (!Array.isArray(entry)) {
    throw new TypeError('each ingredient must be an array of [name, amount]');
  }
  if (entry.length !== 2) {
    throw new TypeError('each ingredient entry needs exactly a name and an amount');
  }
  const [name, amount] = entry;
  if (typeof name !== 'string') {
    throw new TypeError('ingredient name must be a string');
  }
  if (typeof amount !== 'number' || Number.isNaN(amount)) {
    throw new TypeError('ingredient amount must be a number');
  }
  return [name.trim().toLowerCase(), amount];
}

function knead(ingredients) {
  if (!Array.isArray(ingredients)) {
    throw new TypeError('ingredients must be a list of [name, amount] arrays');
  }
  let totalTime = 0;
  let wetMixture = false;
  for (const entry of ingredients) {
    const [name] = validateEntry(entry);
    if (name === 'water') {
      wetMixture = true;
      totalTime += 2;
    } else if (name === 'milk') {
      wetMixture = true;
      totalTime += 3;
    } else if (name === 'flour') {
      if (wetMixture === true) {
        totalTime += 5;
      }
    } else if (name === 'yeast') {
      if (wetMixture === true) {
        totalTime += 4;
      }
    } else if (name === 'salt') {
      totalTime += 1;
    } else if (name === 'sugar') {
      totalTime += 1;
    } else if (name === 'butter') {
      totalTime += 6;
    } else if (name === 'egg') {
      totalTime += 2;
    }
  }
  return totalTime;
}

function formatAmount(name, amount) {
  if (name !== 'egg') {
    return `${amount}g ${name}`;
  }
  if (amount === 1) {
    return '1 egg';
  }
  return `${amount} eggs`;
}

