const COMMANDS = ['drop', 'grab', 'up', 'down', 'left', 'right', 'release', 'return'];

function normalize(token) {
  if (typeof token !== 'string') {
    throw new TypeError('each input must be a string, got: ' + typeof token);
  }
  return token.trim().toLowerCase();
}

function isCommand(token) {
  return COMMANDS.indexOf(token) !== -1;
}

function play(inputs) {
  let x = 0;
  let y = 0;
  let z = 0;
  let holding = false;

  for (const raw of inputs) {
    const cmd = normalize(raw);
    if (cmd === 'drop') {
      if (!holding) z += 10;
    } else if (cmd === 'grab') {
      if (z === 10) holding = true;
    } else if (cmd === 'up') {
      if (z > 0) z -= 10;
    } else if (cmd === 'down') {
      if (z < 10) z += 10;
    } else if (cmd === 'left') {
      if (z === 0) x -= 1;
    } else if (cmd === 'right') {
      if (z === 0) x += 1;
    } else if (cmd === 'release') {
      if (holding === true) holding = false;
    } else if (cmd === 'return') {
      x = 0;
      y = 0;
    }
  }

  return [x, y, z];
}

function parseScript(text) {
  const tokens = text.split(',').map(normalize).filter((t) => t.length !== 0);
  const unknown = tokens.filter((t) => !isCommand(t));
  if (unknown.length > 0) {
    throw new Error('unknown command(s): ' + unknown.join(', '));
  }
  return tokens;
}

function formatPosition(position) {
  if (position.length !== 3) {
    throw new Error('a position needs exactly three coordinates');
  }
  const [x, y, z] = position;
  return `x=${x}, y=${y}, z=${z}`;
}

function report(script) {
  const tokens = parseScript(script);
  const label = tokens.length === 0 ? '(no commands)' : tokens.join(' ');
  return label + ' -> ' + formatPosition(play(tokens));
}

const scripts = [
  'right, drop, grab, up',
  'down, grab, left, release, up, left, left',
  'right, right, return, down',
  '',
];

for (const script of scripts) {
  console.log(report(script));
}

