const CAPACITY = {
  standard: 4,
  front: 2,
  rear: 2,
  vip: 2,
  empty: 0,
  maintenance: 0
};

function normalize(car) {
  if (typeof car !== 'string') {
    throw new TypeError('each car must be a string, got: ' + typeof car);
  }
  return car.trim().toLowerCase();
}

function gateStateFor(kind) {
  if (kind === 'test') {
    return true;
  }
  if (kind === 'disabled') {
    return false;
  }
  return null;
}

function capacityOf(kind) {
  const seats = CAPACITY[kind];
  if (seats === undefined) {
    throw new RangeError('unknown car type: ' + kind);
  }
  return seats;
}

function parseCarList(text) {
  return text.split(',').map(normalize).filter(kind => kind !== '');
}

function summarize(cars) {
  if (Array.isArray(cars) === false) {
    throw new TypeError('cars must be an array');
  }
  let total = 0;
  let loaded = 0;
  let open = false;
  for (const car of cars) {
    const kind = normalize(car);
    const nextState = gateStateFor(kind);
    if (nextState !== null) {
      open = nextState;
      continue;
    }
    const seats = capacityOf(kind);
    if (open === false) {
      continue;
    }
    total += seats;
    if (seats !== 0) {
      loaded += 1;
    }
  }
  return { total, loaded, open };
}

function dispatch(cars) {
  return summarize(cars).total;
}

function formatReport(cars) {
  const summary = summarize(cars);
  const plural = summary.total === 1 ? '' : 's';
  const parts = [summary.total + ' passenger' + plural + ' dispatched'];
  if (summary.loaded === 0) {
    parts.push('no cars were loaded');
  } else {
    parts.push(summary.loaded + ' car(s) loaded');
  }
  parts.push('gate ' + (summary.open ? 'open' : 'closed'));
  return parts.join(', ');
}

const args = process.argv.slice(2);
const cars = args.length === 0
  ? ['test', 'front', 'standard', 'disabled', 'standard']
  : parseCarList(args.join(','));
console.log(cars.join(' -> '));
console.log(formatReport(cars));
console.log('total: ' + dispatch(cars));

module.exports = { dispatch, summarize, formatReport, parseCarList };

