'use strict';

const KNOWN_ACTIONS = ['north', 'south', 'east', 'west', 'spin', 'vacuum', 'mop', 'charge'];

function parseActions(line) {
  return line
    .split(',')
    .map(token => token.trim().toLowerCase())
    .filter(token => token.length !== 0);
}

function findUnknownActions(actions) {
  const unknown = [];
  for (const action of actions) {
    if (KNOWN_ACTIONS.indexOf(action) === -1) {
      unknown.push(action);
    }
  }
  return unknown;
}

function clean(actions) {
  let dirt = 0;
  let battery = 100;
  let stuck = false;
  for (const action of actions) {
    if (action === 'north' && !stuck) {
      battery -= 1;
    } else if (action === 'south' && !stuck) {
      battery -= 1;
    } else if (action === 'east' && !stuck) {
      battery -= 1;
    } else if (action === 'west' && !stuck) {
      battery -= 1;
    } else if (action === 'spin') {
      battery -= 2;
    } else if (action === 'vacuum' && !stuck) {
      dirt += 2;
      battery -= 3;
    } else if (action === 'mop' && !stuck) {
      dirt += 1;
      battery -= 4;
    } else if (action === 'charge') {
      battery = 100;
      stuck = false;
    }
  }
  return [dirt, battery];
}

function batteryStatus(battery) {
  if (battery === 100) {
    return 'full';
  }
  if (battery >= 50) {
    return 'good';
  }
  return battery > 0 ? 'low' : 'empty';
}

function report(line) {
  const actions = parseActions(line);
  const unknown = findUnknownActions(actions);
  if (unknown.length !== 0) {
    return 'invalid actions: ' + unknown.join(', ');
  }
  const [dirt, battery] = clean(actions);
  const unit = dirt === 1 ? 'unit' : 'units';
  return dirt + ' ' + unit + ' of dirt, battery ' + battery + ' (' + batteryStatus(battery) + ')';
}

function main() {
  const runs = [
    'north, vacuum, charge',
    'mop, mop, spin, east',
    'vacuum, wash, north'
  ];
  for (const run of runs) {
    console.log(run + ' -> ' + report(run));
  }
}

main();

module.exports = { clean, parseActions, findUnknownActions, batteryStatus, report };

