const PRICES = {
  vip: 50,
  general: 30,
  student: 20,
  child: 10,
  senior: 15,
  staff: 0,
  press: 0,
};

function normalize(ticket) {
  if (typeof ticket !== 'string') {
    return null;
  }
  const cleaned = ticket.trim().toLowerCase();
  if (cleaned === '') {
    return null;
  }
  return cleaned;
}

function admit(tickets) {
  let totalRevenue = 0;
  let vipGateOpen = true;
  for (const ticket of tickets) {
    const kind = normalize(ticket);
    if (kind === null) {
      continue;
    }
    if (kind === 'fake') {
      vipGateOpen = false;
      continue;
    }
    if (kind === 'vip') {
      if (vipGateOpen) {
        totalRevenue += PRICES.vip;
      }
      continue;
    }
    const price = PRICES[kind];
    if (price !== undefined) {
      totalRevenue += price;
    }
  }
  return totalRevenue;
}

function isRecognized(kind) {
  if (kind === null) {
    return false;
  }
  if (kind === 'fake') {
    return true;
  }
  return PRICES[kind] !== undefined;
}

function countRejected(tickets) {
  let rejected = 0;
  for (const ticket of tickets) {
    if (!isRecognized(normalize(ticket))) {
      rejected += 1;
    }
  }
  return rejected;
}

function report(tickets) {
  const revenue = admit(tickets);
  const rejected = countRejected(tickets);
  const lines = [`tickets: ${tickets.length}`, `revenue: ${revenue}`];
  if (rejected !== 0) {
    lines.push(`unrecognized: ${rejected}`);
  }
  const gateClosed = tickets.some((t) => normalize(t) === 'fake');
  lines.push(`vip gate: ${gateClosed ? 'closed' : 'open'}`);
  return lines.join('\n');
}

