const SHELL_COSTS = {
  peony: 2,
  chrysanthemum: 3,
  willow: 4,
  horsetail: 2,
  crossette: 3,
  ring: 1,
  salute: 5,
  mine: 6
};

function normalizeCue(cue) {
  if (typeof cue !== 'string') {
    throw new TypeError('each cue must be a string');
  }
  return cue.trim().toLowerCase();
}

function shellCost(cue) {
  const cost = SHELL_COSTS[cue];
  if (cost === undefined) {
    return 0;
  }
  return cost;
}

function ignite(cues) {
  if (Array.isArray(cues) !== true) {
    throw new TypeError('cues must be an array of strings');
  }
  let gunpowder = 0;
  let nightTime = true;
  for (const raw of cues) {
    const cue = normalizeCue(raw);
    if (cue === 'day') {
      nightTime = false;
    } else if (nightTime === true) {
      gunpowder += shellCost(cue);
    }
  }
  return gunpowder;
}

function describeCue(cue, nightTime) {
  const name = normalizeCue(cue);
  if (name === 'day') {
    return 'sunrise — the show goes quiet';
  }
  if (nightTime !== true) {
    return `${name} skipped (daylight)`;
  }
  const cost = shellCost(name);
  if (cost === 0) {
    return `${name} is not a known shell`;
  }
  return `${name} burns ${cost} oz`;
}

function formatReport(cues) {
  const lines = [];
  let nightTime = true;
  for (const raw of cues) {
    lines.push('  ' + describeCue(raw, nightTime));
    if (normalizeCue(raw) === 'day') {
      nightTime = false;
    }
  }
  const total = ignite(cues);
  const unit = total === 1 ? 'ounce' : 'ounces';
  lines.push(`  total: ${total} ${unit} of gunpowder`);
  return lines.join('\n');
}

function main() {
  const shows = [
    ['peony', 'willow', 'day', 'chrysanthemum'],
    ['Mine', 'salute', 'ring', 'sparkler'],
    ['day', 'peony', 'crossette']
  ];
  shows.forEach((show, index) => {
    console.log(`Show #${index + 1}`);
    console.log(formatReport(show));
  });
}

main();

