function isValidReading(reading) {
  if (Array.isArray(reading) === false) {
    return false;
  }
  if (reading.length !== 3) {
    return false;
  }
  const tool = reading[0];
  const room = reading[2];
  if (typeof tool !== "string") {
    return false;
  }
  return typeof room === "string";
}

function investigate(readings) {
  let evidence = 0;
  let danger = 0;
  for (const reading of readings) {
    if (isValidReading(reading) === false) {
      continue;
    }
    const [tool, value, room] = reading;
    if (tool === "thermometer") {
      if (value === 0) {
        evidence += 2;
      }
    }
    if (room === "basement") {
      if (tool === "emf") {
        evidence += 3;
      }
    }
    if (tool === "spiritbox") {
      if (value === "demon") {
        danger += 5;
      }
    }
    if (room === "attic") {
      if (tool === "camera") {
        evidence += 4;
      }
    }
    if (tool !== "thermometer") {
      if (danger === 5) {
        evidence += 1;
      }
    }
    if (room !== "basement") {
      if (tool === "emf") {
        danger += 1;
      }
    }
  }
  return [evidence, danger];
}

function classify(danger) {
  if (danger === 0) {
    return "calm";
  }
  return danger < 5 ? "restless" : "hostile";
}

function report(readings) {
  const [evidence, danger] = investigate(readings);
  const noise = readings.filter((r) => isValidReading(r) === false).length;
  const skipped = noise === 0 ? "none" : String(noise);
  return `evidence=${evidence} danger=${danger} (${classify(danger)}), skipped=${skipped}`;
}

const cases = [
  [["emf", 5, "basement"], ["spiritbox", "demon", "hall"], ["camera", "orb", "attic"]],
  [["thermometer", 0, "kitchen"], ["emf", 3, "attic"], ["spiritbox", "silence", "attic"]],
  [["camera", "shadow"], ["emf", 2, "porch"]]
];

for (const readings of cases) {
  console.log(report(readings));
