const STATES = ["loading", "ascending", "descending", "maintenance", "emergency"];
const WEATHERS = ["clear", "wind", "snow", "ice", "hurricane"];

function validateCycle(cycle, index) {
  if (!Array.isArray(cycle)) {
    throw new TypeError("cycle " + index + " is not a list");
  }
  if (cycle.length !== 3) {
    throw new RangeError("cycle " + index + " must hold state, passengers, weather");
  }
  const [state, passengers, weather] = cycle;
  if (typeof state !== "string") {
    throw new TypeError("cycle " + index + " has a non-string cabin state");
  }
  if (typeof weather !== "string") {
    throw new TypeError("cycle " + index + " has a non-string weather reading");
  }
  if (!Number.isInteger(passengers) || passengers < 0) {
    throw new RangeError("cycle " + index + " has an invalid passenger count");
  }
  if (STATES.indexOf(state) === -1) {
    throw new RangeError("cycle " + index + " has unknown cabin state " + state);
  }
  if (WEATHERS.indexOf(weather) === -1) {
    throw new RangeError("cycle " + index + " has unknown weather " + weather);
  }
  return { state: state, passengers: passengers, weather: weather };
}

function applyCycle(tally, cycle) {
  if (cycle.state === "loading") {
    if (cycle.weather === "clear") {
      tally.revenue += 10 * cycle.passengers;
    }
  }
  if (cycle.state === "ascending") {
    if (cycle.weather === "wind") {
      tally.incidents += 1;
    }
  }
  if (cycle.state === "maintenance") {
    if (cycle.passengers === 0) {
      tally.holds += 1;
    }
  }
  if (cycle.weather === "snow") {
    if (cycle.state !== "maintenance") {
      tally.incidents += 2;
    }
  }
  if (cycle.state === "emergency") {
    if (cycle.weather === "ice") {
      tally.revenue -= 50;
    }
  }
  if (cycle.state === "descending") {
    if (cycle.weather !== "clear") {
      tally.incidents += 1;
    }
  }
  if (cycle.weather === "hurricane") {
    tally.incidents = 100;
  }
  return tally;
}

function evaluate(cycles) {
  const tally = { revenue: 0, incidents: 0, holds: 0 };
  cycles.forEach(function (cycle, index) {
    applyCycle(tally, validateCycle(cycle, index));
  });
  return tally;
}

function operate(cycles) {
  const tally = evaluate(cycles);
  return [tally.revenue, tally.incidents];
}

function formatReport(tally) {
  const status = tally.incidents === 0 ? "clear" : tally.incidents >= 100 ? "grounded" : "review";
  const holdText = tally.holds === 1 ? "1 maintenance hold" : tally.holds + " maintenance holds";
  return "revenue " + tally.revenue + ", incidents " + tally.incidents + ", " + holdText + " (" + status + ")";
}

