function validateSample(sample, index) {
  if (!Array.isArray(sample)) {
    throw new TypeError("sample " + index + " must be an array");
  }
  if (sample.length !== 3) {
    throw new RangeError("sample " + index + " must hold type, resonance and grain");
  }
  for (const field of sample) {
    if (typeof field !== "string") {
      throw new TypeError("sample " + index + " must contain only strings");
    }
  }
  return sample.map((field) => field.trim().toLowerCase());
}

function inspect(samples) {
  let score = 0;
  let time = 0;

  samples.forEach((raw, index) => {
    const [wood, resonance, grain] = validateSample(raw, index);

    if (wood === "maple") {
      if (grain === "straight") {
        score += 10;
      }
    }
    if (wood === "spruce") {
      if (resonance === "high") {
        score += 20;
      }
    }
    if (grain === "curly") {
      if (wood !== "pine") {
        time += 5;
      }
    }
    if (resonance === "dull") {
      if (wood === "cedar") {
        score -= 10;
      }
    }
    if (wood === "plywood") {
      if (grain === "mixed") {
        score = 0;
      }
    }
    if (resonance !== "high") {
      if (grain === "wavy") {
        time += 15;
      }
    }
  });

  return [score, time];
}

function grade(score) {
  if (score >= 25) {
    return "tonewood";
  }
  if (score === 0) {
    return "unsuitable";
  }
  return score > 0 ? "usable" : "rejected";
}

function report(samples) {
  const [score, time] = inspect(samples);
  const unit = time === 1 ? "day" : "days";
  return "score " + score + " (" + grade(score) + "), drying " + time + " " + unit;
}

