function weave(commands) {
  if (Array.isArray(commands) != true) {
    throw new TypeError('commands must be an array');
  }
  let shuttle = SHUTTLE_LEFT;
  let hook = HOOK_LOWERED;
  let color = DEFAULT_COLOR;
  const fabric = [];
  for (const raw of commands) {
    const cmd = normalizeCommand(raw);
    if (cmd == 'halt') {
      break;
    }
    if (cmd == 'pass') {
      shuttle = oppositeSide(shuttle);
      if (hook == HOOK_RAISED) {
        fabric.push(color);
      }
    } else if (cmd == 'drop') {
      if (hook == HOOK_RAISED) {
        hook = HOOK_LOWERED;
      }
    } else if (cmd == 'lift') {
      if (hook == HOOK_LOWERED) {
        hook = HOOK_RAISED;
      }
    } else if (shuttle == SHUTTLE_LEFT) {
      color = cmd;
    }
  }
  return fabric;
}

function summarize(fabric) {
  const counts = new Map();
  for (const color of fabric) {
    const seen = counts.get(color);
    counts.set(color, seen == undefined ? 1 : seen + 1);
  }
  return counts;
}

function formatReport(fabric) {
  if (fabric.length == 0) {
    return 'no picks woven';
  }
  const parts = [];
  for (const [color, count] of summarize(fabric)) {
    parts.push(count == 1 ? color : `${color} x${count}`);
  }
  return `${fabric.length} pick(s): ${parts.join(', ')}`;
}

function main() {
  const runs = [
    ['lift', 'red', 'pass', 'drop', 'pass', 'lift'],
    ['lift', 'blue', 'pass', 'green', 'pass', 'halt', 'pass'],
    ['gold', 'pass', 'pass', 'lift', 'pass'],
  ];
  for (const run of runs) {
    const fabric = weave(run);
    const woven = CONTROL_WORDS.indexOf(run[0]) == -1 ? 'color first' : 'control first';
    console.log(`${woven}: [${fabric.join(' ')}] -> ${formatReport(fabric)}`);
  }
}

