const OFFLINE = 'offline';
const CALIBRATING = 'calibrating';
const GHOST_AMPLITUDE = 0;
const ERROR_AMPLITUDE = -1;
const MAJOR_THRESHOLD = 10;

function normalizeReading(raw) {
  if (raw === null) {
    throw new TypeError('a reading must not be null');
  }
  if (typeof raw !== 'object') {
    throw new TypeError('each reading must be an object');
  }
  const wave = String(raw.wave === undefined ? raw.type : raw.wave).toLowerCase();
  const amplitude = Number(raw.amplitude);
  if (Number.isNaN(amplitude)) {
    throw new TypeError('amplitude of a ' + wave + ' reading is not a number');
  }
  const status = String(raw.status === undefined ? 'active' : raw.status).toLowerCase();
  return { wave, amplitude, status };
}

function isSensorUsable(status) {
  if (status === OFFLINE) {
    return false;
  }
  return status !== CALIBRATING;
}

function isGhostSignal(reading) {
  if (reading.wave !== 'primary') {
    return false;
  }
  return reading.amplitude === GHOST_AMPLITUDE;
}

function detect(readings) {
  if (!Array.isArray(readings)) {
    throw new TypeError('readings must be an array');
  }
  let valid = 0;
  let clusters = 0;
  let majorEvents = 0;
  let previousWave = null;
  for (const raw of readings) {
    const reading = normalizeReading(raw);
    if (!isSensorUsable(reading.status)) {
      continue;
    }
    if (isGhostSignal(reading)) {
      continue;
    }
    if (reading.amplitude === ERROR_AMPLITUDE) {
      continue;
    }
    valid += 1;
    if (reading.wave === 'secondary') {
      if (previousWave === 'secondary') {
        clusters += 1;
      }
    } else if (reading.wave === 'surface' && reading.amplitude > MAJOR_THRESHOLD) {
      majorEvents += 1;
    }
    previousWave = reading.wave;
  }
  return [valid, clusters, majorEvents];
}

function formatReport(result) {
  const [valid, clusters, majorEvents] = result;
  const clusterText = clusters === 1 ? '1 cluster' : clusters + ' clusters';
  const eventText = majorEvents === 1 ? '1 major event' : majorEvents + ' major events';
  const status = valid === 0 ? 'no usable data' : valid + ' valid readings';
  return status + ', ' + clusterText + ', ' + eventText;
}

function main() {
  const survey = [
    { wave: 'primary', amplitude: 5, status: 'active' },
    { wave: 'primary', amplitude: 3, status: 'offline' },
    { wave: 'surface', amplitude: 12, status: 'active' },
