    { wave: 'secondary', amplitude: 6, status: 'active' },
    { wave: 'primary', amplitude: 0, status: 'active' },
    { wave: 'surface', amplitude: -1, status: 'active' },
    { wave: 'surface', amplitude: 9, status: 'calibrating' }
  ];
  console.log(detect(survey).join(' '));
  console.log(formatReport(detect(survey)));
}

main();

