  { source: 'interference', polarization: 'linear', width: 300 },
  { source: 'deep space', polarization: 'linear', width: 0 },
  { source: 'deep space', polarization: 'linear', width: 55 },
  { source: 'deep space', polarization: 'unpolarized', width: 12 },
]));

module.exports = { filter, report };

