const KNOWN_DESTINATIONS = ['local', 'remote', 'testing'];

function normalize(value) {
  if (typeof value !== 'string') {
    return '';
  }
  return value.trim().toLowerCase();
}

function isKnownDestination(destination) {
  return KNOWN_DESTINATIONS.indexOf(destination) !== -1;
}

function classify(priority, destination) {
  if (!isKnownDestination(destination)) {
    return 'dead';
  }
  if (destination === 'testing') {
    return 'skip';
  }
  if (priority === 'high') {
    return 'urgent';
  }
  if (priority === 'standard') {
    return destination === 'local' ? 'normal' : 'dead';
  }
  if (priority === 'low') {
    return destination === 'local' ? 'drop' : 'dead';
  }
  return 'dead';
}

function route(messages) {
  if (!Array.isArray(messages)) {
    throw new TypeError('route expects an array of messages');
  }
  const urgent = [];
  const normal = [];
  const deadLetter = [];
  for (const message of messages) {
    const priority = normalize(message.priority);
    const destination = normalize(message.destination);
    const content = typeof message.content === 'string' ? message.content : String(message.content);
    const target = classify(priority, destination);
    if (target === 'urgent') {
      urgent.push(content);
    } else if (target === 'normal') {
      normal.push(content);
    } else if (target === 'dead') {
      deadLetter.push(content);
    }
  }
  return [urgent, normal, deadLetter];
}

function formatReport(lists) {
  const names = ['urgent', 'normal', 'dead letter'];
  const lines = [];
  lists.forEach((list, index) => {
    const noun = list.length === 1 ? 'message' : 'messages';
    const body = list.length === 0 ? '(empty)' : list.join(' | ');
    lines.push(`${names[index]}: ${list.length} ${noun} -> ${body}`);
  });
  return lines.join('\n');
}

const traffic = [
  { priority: 'high', destination: 'local', content: 'FIRE AT MILL' },
  { priority: 'high', destination: 'remote', content: 'BRIDGE DOWN' },
  { priority: 'standard', destination: 'local', content: 'MARKET PRICES' },
