const FRONT_STATES = ['small', 'large'];
const REAR_STATES = ['large', 'medium', 'small'];

function parseAction(action) {
  if (typeof action !== 'string') {
    throw new TypeError('each action must be a string, got ' + typeof action);
  }
  const parts = action.trim().toLowerCase().split(/\s+/);
  if (parts.length !== 2) {
    throw new Error('cannot parse action: ' + action);
  }
  const [part, direction] = parts;
  if (!['front', 'rear'].includes(part)) {
    throw new Error('unknown drivetrain part: ' + part);
  }
  if (!['up', 'down'].includes(direction)) {
    throw new Error('unknown shift direction: ' + direction);
  }
  return { part, direction };
}

function nextFront(front, direction) {
  if (direction === 'up') {
    return front === 'small' ? 'large' : front;
  }
  return front === 'large' ? 'small' : front;
}

function nextRear(rear, direction) {
  const index = REAR_STATES.indexOf(rear);
  const target = direction === 'up' ? index + 1 : index - 1;
  if (target < 0 || target === REAR_STATES.length) {
    return rear;
  }
  return REAR_STATES[target];
}

function isCrossChained(front, rear) {
  if (front !== 'large') {
    return false;
  }
  return rear === 'small';
}

function run(actions) {
  if (!Array.isArray(actions)) {
    throw new TypeError('actions must be an array');
  }
  let front = FRONT_STATES[0];
  let rear = REAR_STATES[0];
  let ignored = 0;
  for (const action of actions) {
    const { part, direction } = parseAction(action);
    let nextF = front;
    let nextR = rear;
    if (part === 'front') {
      nextF = nextFront(front, direction);
    } else {
      nextR = nextRear(rear, direction);
