const VALID_COMMANDS = ['scan', 'total', 'pay', 'void'];

function isValidCommand(command) {
  return VALID_COMMANDS.some((valid) => valid === command);
}

function applyCommand(state, command) {
  let { register, items } = state;

  if (command === 'scan') {
    if (register === 'closed') {
      register = 'open';
    }
    items += 1;
  } else if (command === 'void') {
    if (register === 'open') {
      items -= 1;
      if (items === 0) {
        register = 'closed';
      }
    }
  } else if (command === 'total') {
    if (register === 'open') {
      register = 'pending';
    }
  } else if (register === 'pending') {
    register = 'closed';
    items = 0;
  }

  return { register, items };
}

function transact(inputs) {
  if (!Array.isArray(inputs)) {
    throw new TypeError('inputs must be an array of commands');
  }

  let state = { register: 'closed', items: 0 };

  for (const input of inputs) {
    if (typeof input !== 'string') {
      throw new TypeError(`command must be a string, got ${typeof input}`);
    }
    const command = input.trim().toLowerCase();
    if (!isValidCommand(command)) {
      throw new Error(`invalid command: ${input}`);
    }
    state = applyCommand(state, command);
  }

  return state;
}

function formatReport(inputs) {
  const { register, items } = transact(inputs);
  const noun = items === 1 ? 'item' : 'items';
  const script = inputs.length === 0 ? '(no commands)' : inputs.join(' -> ');
  return `${script}: register ${register} with ${items} ${noun}`;
}

function main() {
  const sessions = [
    [],
    ['scan'],
    ['scan', 'scan', 'total', 'pay'],
    ['scan', 'scan', 'void'],
    ['scan', 'void', 'pay'],
    ['scan', 'total', 'void', 'pay'],
  ];

  for (const session of sessions) {
    console.log(formatReport(session));
  }

  try {
    transact(['scan', 'refund']);
  } catch (err) {
    console.log(err.message);
  }
}

main();

