const HEMISPHERES = ['north', 'south'];
const SEASONS = ['spring', 'summer', 'autumn', 'winter'];
const CLARITIES = ['perfectly clear', 'clear', 'hazy', 'cloudy'];

function validate(settings) {
  if (typeof settings !== 'object') {
    throw new TypeError('settings must be an object');
  }
  if (settings === null) {
    throw new TypeError('settings must not be null');
  }
  const { hemisphere, season, clarity } = settings;
  if (HEMISPHERES.indexOf(hemisphere) === -1) {
    throw new RangeError('unknown hemisphere: ' + hemisphere);
  }
  if (SEASONS.indexOf(season) === -1) {
    throw new RangeError('unknown season: ' + season);
  }
  if (CLARITIES.indexOf(clarity) === -1) {
    throw new RangeError('unknown clarity: ' + clarity);
  }
  return { hemisphere, season, clarity };
}

function locate(settings) {
  const { hemisphere, season, clarity } = validate(settings);
  let stars = [];

  if (clarity === 'perfectly clear') {
    if (season === 'spring') {
      stars.push('Virgo');
    }
  }
  if (hemisphere === 'north') {
    if (season === 'winter') {
      stars.push('Orion');
    }
    if (season === 'summer') {
      stars.push('Cygnus');
    }
  }
  if (hemisphere === 'south') {
    stars.push('Crux');
    if (season === 'autumn') {
      stars.push('Centaurus');
    }
  }

  if (clarity === 'cloudy') {
    stars = [];
  }
  if (clarity === 'hazy') {
    stars = stars.filter(function (name) {
      return name !== 'Orion';
    });
  }
  return stars;
}

function describe(settings) {
  const stars = locate(settings);
  const sky = settings.hemisphere + ' ' + settings.season + ' (' + settings.clarity + ')';
  if (stars.length === 0) {
    return sky + ': nothing visible';
  }
  if (stars.length === 1) {
    return sky + ': ' + stars[0];
  }
  const last = stars[stars.length - 1];
  return sky + ': ' + stars.slice(0, -1).join(', ') + ' and ' + last;
}

function main() {
  const readings = [
    { hemisphere: 'north', season: 'winter', clarity: 'clear' },
    { hemisphere: 'north', season: 'winter', clarity: 'hazy' },
    { hemisphere: 'north', season: 'summer', clarity: 'perfectly clear' },
    { hemisphere: 'south', season: 'autumn', clarity: 'clear' },
    { hemisphere: 'south', season: 'spring', clarity: 'perfectly clear' },
    { hemisphere: 'south', season: 'summer', clarity: 'cloudy' }
  ];
  readings.forEach(function (reading) {
    console.log(describe(reading));
  });
}

main();

