const HARDNESS_CODES = { f: 'soft', '4f': 'soft', '1f': 'medium', p: 'hard', k: 'hard', i: 'hard' };
const WET_LEVELS = ['wet', 'very wet', 'soaked'];

function normalizeText(value, field) {
  if (typeof value !== 'string') {
    throw new TypeError('layer.' + field + ' must be a string');
  }
  return value.trim().toLowerCase();
}

function hardnessClass(hardness) {
  const key = normalizeText(hardness, 'hardness');
  const mapped = HARDNESS_CODES[key];
  if (mapped !== undefined) {
    return mapped;
