const VALID_GROUPS = ['A', 'B', 'AB', 'O'];
const UNIVERSAL_GROUP = 'O';
const PATIENT_GROUP = 'B';
const NEGATIVE_RHESUS = ['-', 'negative'];
const POSITIVE_RHESUS = ['+', 'positive'];
const NEGATIVE_SCREEN = ['negative', 'clear'];
const POSITIVE_SCREEN = ['positive', 'reactive'];

function normalizeGroup(raw) {
  if (typeof raw !== 'string') {
    return 'unknown';
  }
  const group = raw.trim().toUpperCase();
  if (group === 'UNKNOWN') {
    return 'unknown';
  }
  return VALID_GROUPS.indexOf(group) === -1 ? 'unknown' : group;
}

function normalizeRhesus(raw) {
  const value = String(raw).trim().toLowerCase();
  if (NEGATIVE_RHESUS.indexOf(value) !== -1) {
    return 'negative';
  }
  if (POSITIVE_RHESUS.indexOf(value) !== -1) {
    return 'positive';
  }
  return 'unknown';
}

function normalizeScreen(raw) {
  const value = String(raw).trim().toLowerCase();
  if (NEGATIVE_SCREEN.indexOf(value) !== -1) {
    return 'negative';
  }
  if (POSITIVE_SCREEN.indexOf(value) !== -1) {
    return 'positive';
  }
  return 'unknown';
}

function groupCompatibility(group, patientGroup) {
  if (group === 'unknown') {
    return 'unknown';
  }
  if (group === UNIVERSAL_GROUP) {
    return 'universal';
  }
  return group === patientGroup ? 'matched' : 'incompatible';
}

function classify(donation, patientGroup) {
  const compatibility = groupCompatibility(normalizeGroup(donation.group), patientGroup);
  const rhesus = normalizeRhesus(donation.rhesus);
  const screen = normalizeScreen(donation.antibodyScreen);
  if (compatibility === 'unknown') {
    return 'quarantine';
  }
  if (rhesus === 'unknown') {
    return 'quarantine';
  }
  if (screen === 'unknown') {
    return 'quarantine';
  }
  if (screen === 'positive') {
    return 'rejected';
  }
  if (compatibility === 'incompatible') {
    return 'rejected';
  }
  if (rhesus === 'positive') {
    return 'secondary testing';
  }
  return 'accepted';
}

function match(donors) {
  return donors.map((donation) => classify(donation, PATIENT_GROUP));
}

function report(donors, outcomes) {
  const lines = donors.map((donation, index) => {
    const label = normalizeGroup(donation.group);
    const suffix = normalizeRhesus(donation.rhesus) === 'positive' ? '+' : '-';
    return `${donation.id} ${label}${suffix} -> ${outcomes[index]}`;
  });
  const accepted = outcomes.filter((outcome) => outcome === 'accepted').length;
  lines.push(`accepted ${accepted} of ${outcomes.length}`);
  return lines.join('\n');
}

const donations = [
  { id: 'D1', group: 'O', rhesus: 'negative', antibodyScreen: 'negative' },
  { id: 'D2', group: 'B', rhesus: '-', antibodyScreen: 'clear' },
  { id: 'D3', group: 'B', rhesus: '+', antibodyScreen: 'negative' },
  { id: 'D4', group: 'O', rhesus: 'positive', antibodyScreen: 'negative' },
  { id: 'D5', group: 'A', rhesus: '-', antibodyScreen: 'negative' },
  { id: 'D6', group: 'AB', rhesus: '-', antibodyScreen: 'reactive' },
  { id: 'D7', group: '', rhesus: '-', antibodyScreen: 'negative' },
];

console.log(report(donations, match(donations)));

