const VALID_SEVERITIES = ['critical', 'high', 'medium', 'low'];
const VALID_STATUSES = ['consistent', 'intermittent'];

function normalizeField(value) {
  if (typeof value !== 'string') {
    return '';
  }
  return value.trim().toLowerCase();
}

function validateIssue(issue, index) {
  if (issue === null) {
    throw new TypeError('Issue at position ' + index + ' is null');
  }
  if (typeof issue !== 'object') {
    throw new TypeError('Issue at position ' + index + ' is not an object');
  }
  const severity = normalizeField(issue.severity);
  const status = normalizeField(issue.reproducible);
  const component = normalizeField(issue.component);
  if (VALID_SEVERITIES.indexOf(severity) === -1) {
    throw new RangeError('Unknown severity "' + issue.severity + '" at position ' + index);
  }
  if (VALID_STATUSES.indexOf(status) === -1) {
    throw new RangeError('Unknown reproducible status "' + issue.reproducible + '" at position ' + index);
  }
  if (component === '') {
    throw new RangeError('Missing component at position ' + index);
  }
  return { severity: severity, reproducible: status, component: component };
}

function assignTeam(issue) {
  const critical = issue.severity === 'critical';
  const consistent = issue.reproducible === 'consistent';
  if (issue.component === 'documentation') {
    return 'technical writing';
  }
  if (critical && issue.component === 'network') {
    return 'infrastructure';
  }
  if (issue.component === 'database') {
    if (issue.severity === 'high') {
      return 'backend';
    }
  }
  if (critical && consistent) {
    return 'hotfix';
  }
  if (!consistent) {
    return issue.severity === 'low' ? 'backlog' : 'investigation';
  }
  if (issue.component === 'interface') {
    return 'frontend';
  }
  return 'unassigned';
}

function triage(issues) {
  if (!Array.isArray(issues)) {
    throw new TypeError('triage expects an array of issues');
  }
  return issues.map(function (issue, index) {
    return assignTeam(validateIssue(issue, index));
  });
}

function summarize(assignments) {
  const counts = new Map();
  assignments.forEach(function (team) {
    counts.set(team, (counts.get(team) || 0) + 1);
  });
  const lines = [];
  counts.forEach(function (count, team) {
    const label = count === 1 ? 'issue' : 'issues';
    lines.push(team + ': ' + count + ' ' + label);
  });
  return lines.join('\n');
}

const inbox = [
  { severity: 'Critical', reproducible: 'consistent', component: 'database' },
  { severity: 'high', reproducible: 'consistent', component: 'database' },
  { severity: 'low', reproducible: 'intermittent', component: 'network' },
  { severity: 'medium', reproducible: 'intermittent', component: 'interface' },
  { severity: 'medium', reproducible: 'consistent', component: 'interface' },
  { severity: 'critical', reproducible: 'intermittent', component: 'network' },
  { severity: 'low', reproducible: 'consistent', component: 'documentation' },
  { severity: 'medium', reproducible: 'consistent', component: 'build-pipeline' }
];

const routed = triage(inbox);
console.log(routed.join(', '));
console.log(summarize(routed));

