const CHANNELS = ['voice', 'chat', 'text', 'social media', 'email'];
const TIERS = ['platinum', 'gold', 'silver', 'standard'];

function normalizeField(value, name, allowed) {
  if (typeof value !== 'string') {
    throw new TypeError('ticket ' + name + ' must be a string');
  }
  const cleaned = value.trim().toLowerCase().replace(/[\s_-]+/g, ' ');
  if (allowed && allowed.indexOf(cleaned) === -1) {
    throw new RangeError('unknown ' + name + ': ' + value);
  }
  return cleaned;
}

function classify(ticket) {
  const channel = normalizeField(ticket.channel, 'channel', CHANNELS);
  const tier = normalizeField(ticket.tier, 'tier', TIERS);
  const category = normalizeField(ticket.category, 'category', null);

  if (tier === 'platinum') {
    if (channel === 'voice') return 'priority phone support';
  }
  if (tier === 'gold') {
    if (category === 'invoice') return 'technical billing';
  }
  if (channel === 'chat') {
    if (category === 'password') return 'automated recovery';
  }
  if (channel === 'text') {
    if (tier === 'standard') return 'general email';
  }
  if (channel === 'social media') {
    return 'public relations';
  }
  if (tier === 'platinum') {
    if (category === 'refund') return 'retention team';
  }
  if (tier === 'silver') {
    if (channel === 'voice') return 'standard phone support';
  }
  return 'general support queue';
}

