  if (typeof value !== 'string') {
    return '';
  }
  return value.trim().toLowerCase();
}

function validateRegion(region, index) {
  if (!region || typeof region !== 'object') {
    throw new TypeError(`Region at index ${index} must be an object`);
  }
  const damage = normalizeField(region.damage);
  if (DAMAGE_LEVELS.indexOf(damage) === -1) {
    throw new RangeError(`Unknown damage assessment "${region.damage}" at index ${index}`);
  }
  const infrastructure = normalizeField(region.infrastructure);
  if (INFRA_STATES.indexOf(infrastructure) === -1) {
    throw new RangeError(`Unknown infrastructure status "${region.infrastructure}" at index ${index}`);
  }
  const density = normalizeField(region.density);
  if (DENSITIES.indexOf(density) === -1) {
    throw new RangeError(`Unknown population density "${region.density}" at index ${index}`);
  }
  const name = typeof region.name === 'string' ? region.name : `Region ${index + 1}`;
  return { name, damage, infrastructure, density };
}

function methodFor(region) {
  const destroyed = region.infrastructure === 'destroyed';
  const flooded = region.infrastructure === 'flooded';
  const passable = region.infrastructure === 'passable';
  const crowded = region.density === 'high';
  const sparse = region.density === 'low';
  if (destroyed && crowded) {
    return 'air drops';
  }
  if (passable && region.damage === 'severe') {
    return 'ground convoys';
  }
  if (destroyed && sparse) {
    return 'helicopter scouts';
  }
  if (passable && region.damage === 'moderate') {
    return 'standard relief';
  }
  if (flooded && crowded) {
    return 'boat rescue';
  }
  if (flooded && sparse) {
    return 'boat scouts';
  }
  if (region.damage === 'minimal') {
    return 'monitoring';
  }
  return 'assessment pending';
}

function allocate(regions) {
  if (!Array.isArray(regions)) {
