const HULL_STATES = ['intact', 'compromised'];

function parseVessel(raw) {
  if (typeof raw !== 'object') {
    throw new TypeError('each vessel must be an object');
  }
  if (raw === null) {
    throw new TypeError('each vessel must be an object');
  }
  const shipClass = normalizeField(raw.shipClass, 'shipClass');
  const cargoType = normalizeField(raw.cargoType, 'cargoType');
  const hull = normalizeField(raw.hullIntegrity, 'hullIntegrity');
