function normalize(value) {
  if (typeof value !== 'string') {
    return '';
  }
  return value.trim().toLowerCase().replace(/\s+/g, ' ');
}

function readSubmission(submission) {
  if (submission === null || typeof submission !== 'object') {
    return null;
  }
  const asset = normalize(submission.assetType);
  const novelty = normalize(submission.noveltyStatus);
  const sector = normalize(submission.industrySector);
  if (asset === '') {
    return null;
  }
  if (VALID_ASSETS.indexOf(asset) === -1) {
    return null;
  }
  return { asset, novelty, sector };
}

function categorize(record) {
  if (record === null) {
    return 'invalid submission';
  }
  const { asset, novelty, sector } = record;
  if (asset === 'patent' && novelty === 'groundbreaking' && sector === 'medical') {
