function isValidNumber(value) {
  if (typeof value !== 'number') {
    return false;
  }
  return Number.isFinite(value);
}

function simpleCalculator(num1, operator, num2) {
  if (!isValidNumber(num1) || !isValidNumber(num2)) {
    return null;
  }
  if (operator === '+') {
    return num1 + num2;
  }
  if (operator === '-') {
    return num1 - num2;
  }
  if (operator === '*') {
    return num1 * num2;
  }
  if (operator !== '/') {
    return null;
  }
  if (num2 === 0) {
    return null;
  }
  return num1 / num2;
}

function parseExpression(text) {
  if (typeof text !== 'string') {
    return null;
  }
  const match = /^\s*(-?\d+(?:\.\d+)?)\s*(\S+?)\s*(-?\d+(?:\.\d+)?)\s*$/.exec(text);
  if (match === null) {
    return null;
  }
  return {
    left: Number(match[1]),
    operator: match[2],
    right: Number(match[3])
  };
}

function formatNumber(value) {
  const rounded = Math.round(value * 1e6) / 1e6;
  if (rounded === Math.trunc(rounded)) {
    return String(rounded);
  }
  return rounded.toFixed(6).replace(/0+$/, '');
}

function formatResult(text) {
  const parsed = parseExpression(text);
  if (parsed === null) {
    return `${text} => malformed expression`;
  }
  const result = simpleCalculator(parsed.left, parsed.operator, parsed.right);
  if (result === null) {
    return `${text} => null`;
  }
  return `${text} => ${formatNumber(result)}`;
}

function main() {
  const expressions = ['10 + 5', '10 - 5', '10 * 5', '10 / 0', '7 / 2', '3 % 4', '2.5 * -4', 'abc'];
  for (const expression of expressions) {
    console.log(formatResult(expression));
  }
}

main();

