function decodeComponent(text) {
  const normalized = text.replace(/\+/g, ' ');
  if (normalized.indexOf('%') === -1) {
    return normalized;
  }
  try {
    return decodeURIComponent(normalized);
  } catch (err) {
    return normalized;
  }
}

function extractQuery(url) {
  if (typeof url !== 'string') {
    throw new TypeError('parseUrlParams expects a string URL');
  }
  const hashIndex = url.indexOf('#');
  const withoutFragment = hashIndex === -1 ? url : url.slice(0, hashIndex);
  const markIndex = withoutFragment.indexOf('?');
  if (markIndex === -1) {
    return '';
  }
  return withoutFragment.slice(markIndex + 1);
}

function parseUrlParams(url) {
  const query = extractQuery(url);
  const params = {};
  if (query === '') {
    return params;
  }
  for (const pair of query.split('&')) {
    if (pair === '') {
      continue;
    }
    const separator = pair.indexOf('=');
    const rawKey = separator === -1 ? pair : pair.slice(0, separator);
    const rawValue = separator === -1 ? '' : pair.slice(separator + 1);
    const key = decodeComponent(rawKey);
    if (key === '') {
      continue;
    }
    params[key] = decodeComponent(rawValue);
  }
  return params;
}

function describeParams(url) {
  const params = parseUrlParams(url);
  const keys = Object.keys(params);
  if (keys.length === 0) {
    return url + ' -> no parameters';
  }
  const parts = keys.map(function (key) {
    const value = params[key];
    return value === '' ? key + '=(empty)' : key + '=' + value;
  });
  return url + ' -> ' + parts.join(', ');
}

const samples = [
  'http://example.com?name=Alice&age=30',
  'http://example.com',
  'http://example.com?q=hello+world&lang=en#results',
  'http://example.com?flag&city=S%C3%A3o%20Paulo',
  'http://example.com?'
];

for (const sample of samples) {
  console.log(describeParams(sample));
}

const first = parseUrlParams(samples[0]);
console.log('age is a string:', typeof first.age === 'string');
console.log('name matches:', first.name === 'Alice');

module.exports = { parseUrlParams, describeParams, decodeComponent };

