function parseTime(timeString) {
  if (typeof timeString !== 'string') {
    return null;
  }
  const parts = timeString.split(':');
  if (parts.length !== 2) {
    return null;
  }
  if (parts[0].length !== 2) {
    return null;
  }
  if (parts[1].length !== 2) {
    return null;
  }
  const hours = Number(parts[0]);
  const minutes = Number(parts[1]);
  if (!Number.isInteger(hours) || !Number.isInteger(minutes)) {
    return null;
  }
  if (hours < 0 || hours > 23 || minutes < 0 || minutes > 59) {
    return null;
  }
  return hours * 60 + minutes;
}

function findConflict(tasks, startTime) {
  for (const task of tasks) {
    if (task.time === startTime) {
      return task;
    }
  }
  return null;
}

function addTask(schedule, taskName, startTime) {
  if (typeof taskName !== 'string') {
    throw new Error('taskName must be a string');
  }
  const name = taskName.trim();
  if (name === '') {
    throw new Error('taskName must not be empty');
  }
  if (parseTime(startTime) === null) {
    throw new Error('startTime must be in HH:MM format');
  }
  if (schedule.today === undefined) {
    schedule.today = [];
  }
  const clash = findConflict(schedule.today, startTime);
  if (clash !== null) {
    throw new Error('slot ' + startTime + ' already taken by ' + clash.name);
  }
  schedule.today.push({ name: name, time: startTime });
  return schedule;
}

function formatSchedule(schedule) {
  const tasks = schedule.today === undefined ? [] : schedule.today.slice();
  if (tasks.length === 0) {
    return 'today: (nothing planned)';
  }
  tasks.sort((a, b) => parseTime(a.time) - parseTime(b.time));
  const lines = tasks.map((task) => '  ' + task.time + ' - ' + task.name);
  return 'today:\n' + lines.join('\n');
}

function main() {
  let schedule = addTask({}, 'Meeting', '10:00');
  schedule = addTask(schedule, 'Lunch', '12:00');
  schedule = addTask(schedule, 'Call', '14:00');

  const attempts = [['Standup', '10:00'], ['Review', '25:00'], ['Gym', '18:30']];
  for (const [name, time] of attempts) {
    try {
      addTask(schedule, name, time);
      console.log('added ' + name);
    } catch (err) {
      console.log('rejected ' + name + ': ' + err.message);
    }
  }

  console.log(formatSchedule(schedule));
  console.log('task count: ' + schedule.today.length);
}

main();

