const CHOICES = ['rock', 'paper', 'scissors'];

const BEATS = {
  rock: 'scissors',
  paper: 'rock',
  scissors: 'paper'
};

function normalizeChoice(choice) {
  if (typeof choice !== 'string') {
    return null;
  }
  const cleaned = choice.trim().toLowerCase();
  const match = CHOICES.find((name) => name === cleaned);
  return match === undefined ? null : match;
}

function randomChoice() {
  const index = Math.floor(Math.random() * CHOICES.length);
  return CHOICES[index];
}

function judge(playerChoice, computerChoice) {
  if (playerChoice === computerChoice) {
    return 'Tie';
  }
  if (BEATS[playerChoice] === computerChoice) {
    return 'Win';
  }
  return 'Loss';
}

function playRockPaperScissors(playerChoice) {
  const player = normalizeChoice(playerChoice);
  if (player === null) {
    throw new TypeError('playerChoice must be one of: ' + CHOICES.join(', '));
  }
  return judge(player, randomChoice());
}

function playSeries(playerChoice, rounds) {
  if (!Number.isInteger(rounds) || rounds < 1) {
    throw new RangeError('rounds must be a positive integer');
  }
  const tally = { Win: 0, Loss: 0, Tie: 0 };
  for (let i = 0; i < rounds; i += 1) {
    const outcome = playRockPaperScissors(playerChoice);
    tally[outcome] += 1;
  }
  return tally;
}

function formatTally(playerChoice, tally) {
  const total = tally.Win + tally.Loss + tally.Tie;
  const verdict =
    tally.Win === tally.Loss ? 'even overall' : tally.Win > tally.Loss ? 'ahead overall' : 'behind overall';
  const parts = ['Win', 'Loss', 'Tie'].map((key) => {
    const share = ((tally[key] / total) * 100).toFixed(1);
    const label = tally[key] === 1 ? 'round' : 'rounds';
    return `${key}: ${tally[key]} ${label} (${share}%)`;
  });
  return `Always playing "${playerChoice}" over ${total} rounds -> ${parts.join(', ')}; ${verdict}.`;
}

function main() {
  const single = playRockPaperScissors('rock');
  console.log(`Single round with rock: ${single}`);
  if (single === 'Tie') {
    console.log('The computer mirrored the choice.');
  }

  for (const choice of CHOICES) {
    console.log(formatTally(choice, playSeries(choice, 300)));
  }
}

main();

module.exports = { playRockPaperScissors, playSeries, judge, normalizeChoice, formatTally };

