const EMAIL_PATTERN = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g;

function extractEmails(text) {
  if (typeof text !== 'string') {
    throw new TypeError('extractEmails expects a string');
  }
  const matches = text.match(EMAIL_PATTERN);
  if (matches === null) {
    return [];
  }
  return matches.filter(isWellFormed);
}

function isWellFormed(address) {
  const parts = address.split('@');
  if (parts.length !== 2) {
    return false;
  }
  const local = parts[0];
  const domain = parts[1];
  if (local.charAt(0) === '.') {
    return false;
  }
  if (local.charAt(local.length - 1) === '.') {
    return false;
  }
  if (local.includes('..')) {
    return false;
  }
  if (domain.includes('..')) {
    return false;
  }
  return domain.charAt(0) !== '-';
}

function normalize(address) {
  const at = address.lastIndexOf('@');
  return address.slice(0, at) + '@' + address.slice(at + 1).toLowerCase();
}

function uniqueEmails(text) {
  const seen = new Set();
  const result = [];
  for (const address of extractEmails(text)) {
    const normalized = normalize(address);
    if (!seen.has(normalized)) {
      seen.add(normalized);
      result.push(normalized);
    }
  }
  return result;
}

function groupByDomain(text) {
  const groups = new Map();
  for (const address of uniqueEmails(text)) {
    const domain = address.slice(address.lastIndexOf('@') + 1);
    const bucket = groups.get(domain);
    if (bucket === undefined) {
      groups.set(domain, [address]);
    } else {
      bucket.push(address);
    }
  }
  return groups;
}

function report(text) {
  const groups = groupByDomain(text);
  if (groups.size === 0) {
    return 'no email addresses found';
  }
  const lines = [];
  for (const [domain, addresses] of groups) {
    const label = addresses.length === 1 ? 'address' : 'addresses';
    lines.push(domain + ' (' + addresses.length + ' ' + label + '): ' + addresses.join(', '));
  }
  return lines.join('\n');
}

const samples = [
  'Contact us at test@example.com or support@domain.net',
  'No emails here.',
  'Sales: sales@Domain.NET, sales@domain.net; bad: ..oops@domain.net'
];

for (const sample of samples) {
  console.log(JSON.stringify(extractEmails(sample)));
  console.log(report(sample));
}

