function parseDimension(value) {
  if (typeof value === 'number') {
    return Number.isFinite(value) ? value : NaN;
  }
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (trimmed === '') {
      return NaN;
    }
    return Number(trimmed);
  }
  return NaN;
}

function calculateRectangleArea(width, height) {
  const w = parseDimension(width);
  const h = parseDimension(height);
  if (Number.isNaN(w) || Number.isNaN(h)) {
    throw new TypeError('width and height must be finite numbers');
  }
  if (w < 0 || h < 0) {
    throw new RangeError('width and height must not be negative');
  }
  return w * h;
}

function describeShape(width, height) {
  const w = parseDimension(width);
  const h = parseDimension(height);
  if (Math.min(w, h) === 0) {
    return 'degenerate';
  }
  if (w === h) {
    return 'square';
  }
  return w > h ? 'landscape rectangle' : 'portrait rectangle';
}

function formatArea(area) {
  const rounded = Math.round(area * 1000) / 1000;
  if (rounded === Math.trunc(rounded)) {
    return String(Math.trunc(rounded));
  }
  return rounded.toFixed(3).replace(/0+$/, '');
}

function report(width, height) {
  try {
    const area = calculateRectangleArea(width, height);
    const shape = describeShape(width, height);
    const note = shape === 'square' ? ' (equal sides)' : '';
    return `${width} x ${height} -> area ${formatArea(area)}${note}`;
  } catch (err) {
    const kind = err instanceof RangeError ? 'range' : 'type';
    return `${width} x ${height} -> ${kind} error: ${err.message}`;
  }
}

function main() {
  const cases = [[5, 10], [2.5, 4], [7, 7], ['3', '0.5'], [0, 8], [-2, 3], ['abc', 1]];
  for (const [width, height] of cases) {
    console.log(report(width, height));
  }
  const totalArea = cases
    .filter(([w, h]) => parseDimension(w) >= 0 && parseDimension(h) >= 0)
    .reduce((sum, [w, h]) => sum + calculateRectangleArea(w, h), 0);
  console.log(`valid total area: ${formatArea(totalArea)}`);
}

if (typeof require !== 'undefined') {
  if (require.main === module) {
    main();
  }
}

module.exports = { calculateRectangleArea, describeShape, formatArea, report };

