'use strict';

function validateNumber(value, label) {
  if (typeof value !== 'number') {
    throw new TypeError(label + ' must be a number');
  }
  if (Number.isNaN(value)) {
    throw new TypeError(label + ' must not be NaN');
  }
  return value;
}

function guessNumber(target, guess) {
  validateNumber(target, 'target');
  validateNumber(guess, 'guess');
  if (guess === target) {
    return 'Correct!';
  }
  return guess > target ? 'Too high' : 'Too low';
}

function playRound(target, guesses) {
  const history = [];
  for (let i = 0; i < guesses.length; i += 1) {
    const guess = guesses[i];
    const verdict = guessNumber(target, guess);
    history.push({ guess: guess, verdict: verdict, attempt: i + 1 });
    if (verdict === 'Correct!') {
      break;
    }
  }
  return history;
}

function summarize(target, history) {
  let solved = false;
  if (history.length > 0) {
    solved = history[history.length - 1].verdict === 'Correct!';
  }
  return {
    target: target,
    attempts: history.length,
    solved: solved
  };
}

function arrowFor(verdict) {
  if (verdict === 'Too high') {
    return 'v';
  }
  if (verdict === 'Too low') {
    return '^';
  }
  return '=';
}

function formatHistory(history) {
  return history.map(function (entry) {
    const arrow = arrowFor(entry.verdict);
    return '#' + entry.attempt + ' ' + entry.guess + ' ' + arrow + ' ' + entry.verdict;
  }).join('\n');
}

function main() {
  const target = 42;
  const history = playRound(target, [10, 80, 50, 42, 7]);
  console.log(formatHistory(history));

  const summary = summarize(target, history);
  const outcome = summary.solved
    ? 'found in ' + summary.attempts + ' attempts'
    : 'not found after ' + summary.attempts + ' attempts';
  console.log('Result: ' + outcome);

  console.log(guessNumber(10, 5));
  console.log(guessNumber(7, 7));
}

main();

module.exports = { guessNumber: guessNumber, playRound: playRound, summarize: summarize };

