function startsWith(str, prefix) {
  if (typeof str !== 'string') {
    throw new TypeError('startsWith: first argument must be a string');
  }
  if (typeof prefix !== 'string') {
    throw new TypeError('startsWith: second argument must be a string');
  }
  if (prefix.length === 0) {
    return true;
  }
  if (prefix.length > str.length) {
    return false;
  }
  for (let i = 0; i < prefix.length; i += 1) {
    if (str[i] !== prefix[i]) {
      return false;
    }
  }
  return true;
}

function startsWithIgnoreCase(str, prefix) {
  return startsWith(str.toLowerCase(), prefix.toLowerCase());
}

function commonPrefixLength(str, prefix) {
  const limit = Math.min(str.length, prefix.length);
  let i = 0;
  while (i < limit && str[i] === prefix[i]) {
    i += 1;
  }
  return i;
}

function stripPrefix(str, prefix) {
  return startsWith(str, prefix) ? str.slice(prefix.length) : str;
}

function describe(str, prefix) {
  if (startsWith(str, prefix)) {
    const rest = stripPrefix(str, prefix);
    const tail = rest.length === 0 ? '(nothing left)' : `remainder "${rest}"`;
    return `"${str}" starts with "${prefix}" -> true, ${tail}`;
  }
  const shared = commonPrefixLength(str, prefix);
  const note = startsWithIgnoreCase(str, prefix)
    ? 'differs only in letter case'
    : `first ${shared} character(s) agree`;
  return `"${str}" starts with "${prefix}" -> false, ${note}`;
}

function main() {
  const cases = [
    ['Hello World', 'Hello'],
    ['JavaScript', 'JavaScripX'],
    ['JavaScript', 'javascript'],
    ['abc', ''],
    ['abc', 'abcd'],
    ['prefix-only', 'prefix-only'],
  ];
  for (const [str, prefix] of cases) {
    console.log(describe(str, prefix));
  }
}

main();

module.exports = {
  startsWith,
  startsWithIgnoreCase,
  commonPrefixLength,
  stripPrefix,
  describe,
};

