function isSameValue(a, b) {
  if (Number.isNaN(a)) {
    return Number.isNaN(b);
  }
  return a === b;
}

function searchFrom(arr, element, start) {
  for (let i = start; i < arr.length; i += 1) {
    if (isSameValue(arr[i], element)) {
      return i;
    }
  }
  return -1;
}

function findFirstIndex(arr, element) {
  if (!Array.isArray(arr)) {
    throw new TypeError('findFirstIndex expects an array as its first argument');
  }
  return searchFrom(arr, element, 0);
}

function findLastIndex(arr, element) {
  for (let i = arr.length - 1; i >= 0; i -= 1) {
    if (isSameValue(arr[i], element)) {
      return i;
    }
  }
  return -1;
}

function findAllIndices(arr, element) {
  const hits = [];
  let index = searchFrom(arr, element, 0);
  while (index !== -1) {
    hits.push(index);
    index = searchFrom(arr, element, index + 1);
  }
  return hits;
}

function describeValue(value) {
  if (typeof value === 'string') {
    return `'${value}'`;
  }
  return String(value);
}

function report(arr, element) {
  const first = findFirstIndex(arr, element);
  const label = describeValue(element);
  if (first === -1) {
    return `${label} is not present`;
  }
  const last = findLastIndex(arr, element);
  if (last === first) {
    return `${label} occurs once, at index ${first}`;
  }
  const all = findAllIndices(arr, element);
  return `${label} occurs ${all.length} times, first at ${first}, last at ${last}`;
}

const numbers = [1, 5, 2, 8, 2, NaN];
const letters = ['a', 'b', 'c'];

console.log(findFirstIndex(numbers, 2));
console.log(findFirstIndex(letters, 'd'));
console.log(findFirstIndex(numbers, NaN));
console.log(report(numbers, 2));
console.log(report(numbers, 8));
console.log(report(letters, 'd'));

module.exports = { findFirstIndex, findLastIndex, findAllIndices, report };

