const HEADS = 'Heads';
const TAILS = 'Tails';

function coinFlip() {
  return Math.random() < 0.5 ? HEADS : TAILS;
}

function flipMany(count) {
  if (typeof count !== 'number' || !Number.isInteger(count) || count < 1) {
    throw new TypeError('count must be a positive integer');
  }
  const results = [];
  for (let i = 0; i < count; i += 1) {
    results.push(coinFlip());
  }
  return results;
}

function tally(results) {
  const counts = { [HEADS]: 0, [TAILS]: 0 };
  for (const side of results) {
    if (side === HEADS) {
      counts[HEADS] += 1;
    } else if (side === TAILS) {
      counts[TAILS] += 1;
    } else {
      throw new Error(`unexpected flip result: ${String(side)}`);
    }
  }
  return counts;
}

function longestRun(results) {
  let best = 0;
  let current = 0;
  let previous = null;
  for (const side of results) {
    current = side === previous ? current + 1 : 1;
    previous = side;
    if (current > best) {
      best = current;
    }
  }
  return best;
}

function percentage(part, whole) {
  if (whole === 0) {
    return '0.0%';
  }
  return `${((part / whole) * 100).toFixed(1)}%`;
}

function formatReport(results) {
  const counts = tally(results);
  const total = results.length;
  const lines = [
    `Flips: ${total}`,
    `${HEADS}: ${counts[HEADS]} (${percentage(counts[HEADS], total)})`,
    `${TAILS}: ${counts[TAILS]} (${percentage(counts[TAILS], total)})`,
    `Longest streak: ${longestRun(results)}`
  ];
  const leader = counts[HEADS] === counts[TAILS]
    ? 'Result: perfectly even'
    : `Result: ${counts[HEADS] > counts[TAILS] ? HEADS : TAILS} ahead`;
  lines.push(leader);
  return lines.join('\n');
}

function main(argv) {
  const requested = argv.length === 0 ? '20' : argv[0];
  const count = Number.parseInt(requested, 10);
  if (Number.isNaN(count)) {
    console.error(`not a number: ${requested}`);
    return 1;
  }
  const results = flipMany(count);
  console.log(`First flip: ${results[0]}`);
  console.log(formatReport(results));
  return 0;
}

if (require.main === module) {
  process.exitCode = main(process.argv.slice(2));
}

module.exports = { coinFlip, flipMany, tally, longestRun, formatReport, main };

