'use strict';

function hammingWeight(n) {
  if (typeof n !== 'number') {
    throw new TypeError('hammingWeight expects a number, got ' + typeof n);
  }
  if (!Number.isInteger(n) || n < 0) {
    throw new RangeError('hammingWeight expects a non-negative integer');
  }
  let count = 0;
  let value = n;
  while (value > 0) {
    if (value % 2 === 1) {
      count += 1;
    }
    value = Math.floor(value / 2);
  }
  return count;
}

function parseUnsigned(text) {
  const trimmed = String(text).trim();
  if (trimmed === '') {
    throw new SyntaxError('empty input is not a number');
  }
  const prefix = trimmed.slice(0, 2).toLowerCase();
  const binary = prefix === '0b';
  const parsed = binary ? parseInt(trimmed.slice(2), 2) : Number(trimmed);
  if (Number.isNaN(parsed)) {
    throw new SyntaxError('cannot parse "' + trimmed + '" as an unsigned integer');
  }
  return parsed;
}

function describe(n) {
  const weight = hammingWeight(n);
  const plural = weight === 1 ? 'bit' : 'bits';
  return n + ' (0b' + n.toString(2) + ') has ' + weight + ' set ' + plural;
}

function weightHistogram(values) {
  const buckets = new Map();
  for (const value of values) {
    const weight = hammingWeight(value);
    const current = buckets.get(weight);
    buckets.set(weight, current === undefined ? 1 : current + 1);
  }
  return buckets;
}

function main(args) {
  const inputs = args.length === 0 ? ['1', '7', '0', '0b101101', '255', '1024'] : args;
  const numbers = [];
  for (const raw of inputs) {
    try {
      numbers.push(parseUnsigned(raw));
    } catch (err) {
      console.error('skipping ' + raw + ': ' + err.message);
    }
  }
  numbers.forEach(function (n) {
    console.log(describe(n));
  });
  const histogram = weightHistogram(numbers);
  const weights = Array.from(histogram.keys()).sort(function (a, b) {
    return a - b;
  });
  for (const weight of weights) {
    const count = histogram.get(weight);
    const noun = count === 1 ? 'value' : 'values';
    console.log('weight ' + weight + ': ' + count + ' ' + noun);
  }
}

main(process.argv.slice(2));

module.exports = { hammingWeight, parseUnsigned, describe, weightHistogram };

