}

function popcount(n) {
  let bits = 0;
  let rest = n >>> 0;
  while (rest !== 0) {
    bits += rest & 1;
    rest >>>= 1;
  }
  return bits;
}

function hammingDistance(x, y) {
  assertInteger(x, 'x');
  assertInteger(y, 'y');
  if (x === y) {
    return 0;
  }
  return popcount(x ^ y);
}

