function parsePath(path) {
  if (typeof path !== 'string') {
    return null;
  }
  const trimmed = path.trim();
  if (trimmed === '') {
    return null;
  }
  const keys = [];
  for (const raw of trimmed.split('.')) {
    const key = raw.trim();
    if (key === '') {
      return null;
    }
    keys.push(key);
  }
  return keys;
}

function isTraversable(value) {
  if (value === null) {
    return false;
  }
  const type = typeof value;
  if (type === 'object') {
    return true;
  }
  return type === 'function';
}

function getNestedProperty(obj, path) {
  const keys = parsePath(path);
  if (keys === null) {
    return undefined;
  }
  let current = obj;
  for (const key of keys) {
    if (!isTraversable(current)) {
      return undefined;
    }
    current = current[key];
  }
  return current;
}

function hasNestedProperty(obj, path) {
  const keys = parsePath(path);
  if (keys === null) {
    return false;
  }
  let current = obj;
  for (const key of keys) {
    if (!isTraversable(current)) {
      return false;
    }
    if (!Object.prototype.hasOwnProperty.call(current, key)) {
      return false;
    }
    current = current[key];
  }
  return true;
}

function describe(obj, path) {
  const value = getNestedProperty(obj, path);
  if (value === undefined) {
    const reason = hasNestedProperty(obj, path) ? 'stored as undefined' : 'missing';
    return `${path} -> undefined (${reason})`;
  }
  if (typeof value === 'string') {
    return `${path} -> "${value}"`;
  }
  return `${path} -> ${JSON.stringify(value)}`;
}

const data = { a: { b: { c: 1 }, list: [10, 20] }, name: 'root', blank: undefined };
const paths = ['a.b.c', 'a.c', 'a.list.1', 'name', 'blank', 'name.length', 'a..b', ''];
for (const path of paths) {
  console.log(describe(data, path));
}

module.exports = { getNestedProperty, hasNestedProperty, parsePath, describe };

