'use strict';

function validateInput(nums) {
  if (!Array.isArray(nums)) {
    throw new TypeError('findSingleNumber expects an array of numbers');
  }
  if (nums.length === 0) {
    throw new RangeError('findSingleNumber expects a non-empty array');
  }
  for (let i = 0; i < nums.length; i += 1) {
    const value = nums[i];
    if (typeof value !== 'number') {
      throw new TypeError(`element at index ${i} is not a number`);
    }
    if (!Number.isInteger(value)) {
      throw new TypeError(`element at index ${i} is not an integer`);
    }
  }
}

function findSingleNumber(nums) {
  validateInput(nums);
  let single = 0;
  for (const value of nums) {
    single ^= value;
  }
  return single;
}

function countOccurrences(nums) {
  const counts = new Map();
  for (const value of nums) {
    const seen = counts.get(value);
    counts.set(value, seen === undefined ? 1 : seen + 1);
  }
  return counts;
}

function findLonelyValues(nums) {
  const lonely = [];
  for (const [value, count] of countOccurrences(nums)) {
    if (count % 2 === 1) {
      lonely.push(value);
    }
  }
  return lonely;
}

function parseNumberList(text) {
  return text
    .split(',')
    .map((part) => part.trim())
    .filter((part) => part !== '')
    .map((part) => {
      const value = Number(part);
      if (Number.isNaN(value)) {
        throw new TypeError(`cannot parse "${part}" as a number`);
      }
      return value;
    });
}

function describe(text) {
  const nums = parseNumberList(text);
  const answer = findSingleNumber(nums);
  const lonely = findLonelyValues(nums);
  const note = lonely.length === 1
    ? 'exactly one unpaired element'
    : `unpaired elements: [${lonely.join(', ')}]`;
  return `[${nums.join(', ')}] -> ${answer} (${note})`;
}

function main() {
  const inputs = ['2, 2, 1', '4, 1, 2, 1, 2', '-7', '3, 5, 3, 5, 9, 11, 11'];
  for (const input of inputs) {
    console.log(describe(input));
  }
}

module.exports = { findSingleNumber, findLonelyValues, parseNumberList, describe };

if (require.main === module) {
  main();
}

