function parseSeries(text) {
  if (typeof text !== 'string') {
    throw new TypeError('parseSeries expects a string of comma-separated numbers');
  }
  const trimmed = text.trim();
  if (trimmed === '') {
    return [];
  }
  return trimmed.split(',').map(function (token, index) {
    if (token.trim() === '') {
      throw new SyntaxError('empty field at position ' + index);
    }
    const value = Number(token);
    if (Number.isNaN(value)) {
      throw new SyntaxError('field ' + index + ' is not a number: ' + token.trim());
    }
    return value;
  });
}

function validateInput(nums) {
  if (!Array.isArray(nums)) {
    throw new TypeError('countInversions expects an array of numbers');
  }
  for (let i = 0; i < nums.length; i += 1) {
    if (typeof nums[i] !== 'number') {
      throw new TypeError('element at index ' + i + ' is not a number');
    }
    if (Number.isNaN(nums[i])) {
      throw new RangeError('element at index ' + i + ' is NaN');
    }
  }
}

function mergeCount(left, right, out) {
  let i = 0;
  let j = 0;
  let k = 0;
  let inversions = 0;
  while (i < left.length && j < right.length) {
    if (left[i] > right[j]) {
      out[k] = right[j];
      j += 1;
      inversions += left.length - i;
    } else {
      out[k] = left[i];
      i += 1;
    }
    k += 1;
  }
  while (i < left.length) {
    out[k] = left[i];
    i += 1;
    k += 1;
  }
  while (j < right.length) {
    out[k] = right[j];
    j += 1;
    k += 1;
  }
  return inversions;
}

function sortAndCount(nums) {
  if (nums.length <= 1) {
    return { sorted: nums.slice(), inversions: 0 };
  }
  const mid = Math.floor(nums.length / 2);
  const leftPart = sortAndCount(nums.slice(0, mid));
  const rightPart = sortAndCount(nums.slice(mid));
  const merged = new Array(nums.length);
  const crossing = mergeCount(leftPart.sorted, rightPart.sorted, merged);
  return {
    sorted: merged,
    inversions: leftPart.inversions + rightPart.inversions + crossing
  };
}

function countInversions(nums) {
  validateInput(nums);
  return sortAndCount(nums).inversions;
}

function classify(total, length) {
  if (total === 0) {
    return 'already sorted';
  }
  if (total === (length * (length - 1)) / 2) {
    return 'strictly descending';
  }
  return 'partially ordered';
}

