function parseCoordinate(token) {
  const trimmed = String(token).trim();
  if (trimmed === '') {
    return NaN;
  }
  return Number(trimmed);
}

function assertCoordinate(value, name) {
  if (typeof value !== 'number') {
    throw new TypeError(name + ' must be a number');
  }
  if (Number.isNaN(value)) {
    throw new RangeError(name + ' must not be NaN');
  }
}

function getQuadrant(x, y) {
  assertCoordinate(x, 'x');
  assertCoordinate(y, 'y');
  if (x === 0) {
    return 0;
  }
  if (y === 0) {
    return 0;
  }
  if (x > 0) {
    return y > 0 ? 1 : 4;
  }
  return y > 0 ? 2 : 3;
}

function describeQuadrant(quadrant) {
  if (quadrant === 0) {
    return 'on an axis or at the origin';
