function isPlainObject(value) {
  return Object.prototype.toString.call(value) === '[object Object]';
}

function validateInventory(inventory) {
  if (!isPlainObject(inventory)) {
    throw new TypeError('inventory must be a plain object');
  }
  for (const key of Object.keys(inventory)) {
    const qty = inventory[key];
    if (typeof qty !== 'number' || Number.isNaN(qty)) {
      throw new TypeError('inventory quantity for "' + key + '" must be a number');
    }
  }
  return inventory;
}

function normalizeName(itemName) {
  if (typeof itemName !== 'string') {
    throw new TypeError('itemName must be a string');
  }
  const trimmed = itemName.trim();
  if (trimmed === '') {
    throw new RangeError('itemName must not be empty');
  }
  return trimmed;
}

function restockItem(inventory, itemName, quantityToAdd) {
  validateInventory(inventory);
  const name = normalizeName(itemName);
  if (typeof quantityToAdd !== 'number' || !Number.isFinite(quantityToAdd)) {
    throw new TypeError('quantityToAdd must be a finite number');
  }
  const current = Object.prototype.hasOwnProperty.call(inventory, name) ? inventory[name] : 0;
  inventory[name] = current + quantityToAdd;
  return inventory;
}

function removeEmptyItems(inventory) {
  validateInventory(inventory);
  const removed = [];
  for (const key of Object.keys(inventory)) {
    if (inventory[key] === 0) {
      removed.push(key);
      delete inventory[key];
    }
  }
  return removed;
}

function applyRestockList(inventory, orders) {
  if (!Array.isArray(orders)) {
    throw new TypeError('orders must be an array');
  }
  for (const order of orders) {
    restockItem(inventory, order.item, order.amount);
  }
  return inventory;
}

function formatInventory(inventory) {
  validateInventory(inventory);
  const names = Object.keys(inventory).sort();
  if (names.length === 0) {
    return '(empty inventory)';
  }
  return names
    .map((name) => {
      const qty = inventory[name];
      const unit = qty === 1 ? 'unit' : 'units';
      return name + ': ' + qty + ' ' + unit;
    })
    .join('\n');
}

const stock = { apple: 10, pear: 1, plum: 3 };
restockItem(stock, 'apple', 5);
restockItem(stock, 'banana', 5);
applyRestockList(stock, [
  { item: 'pear', amount: 2 },
  { item: 'plum', amount: -3 },
  { item: 'cherry', amount: 12 }
]);
const cleared = removeEmptyItems(stock);
console.log(formatInventory(stock));
console.log('Cleared out: ' + (cleared.length === 0 ? 'nothing' : cleared.join(', ')));

