function parseCase(line) {
  const trimmed = line.trim();
  if (trimmed === '') {
    return null;
  }
  const fields = trimmed.split(/\s+/);
  if (fields.length !== 3) {
    throw new TypeError(`expected 3 values per line, got ${fields.length}`);
  }
  return fields.map(Number);
}

function validateDimension(value, name) {
  if (typeof value !== 'number') {
    return `${name} must be a number, got ${typeof value}`;
  }
  if (Number.isNaN(value)) {
    return `${name} is not a valid number`;
  }
  if (!Number.isFinite(value)) {
    return `${name} must be finite`;
  }
  if (value <= 0) {
    return `${name} must be positive, got ${value}`;
  }
  return null;
}

function calculateTrapezoidArea(b1, b2, h) {
  const inputs = [[b1, 'b1'], [b2, 'b2'], [h, 'h']];
  for (const [value, name] of inputs) {
    const problem = validateDimension(value, name);
    if (problem !== null) {
      throw new TypeError(problem);
    }
  }
  return 0.5 * (b1 + b2) * h;
}

function classifyTrapezoid(b1, b2) {
  if (b1 === b2) {
    return 'parallelogram';
  }
  return b1 > b2 ? 'longer base first' : 'longer base second';
}

function formatArea(area) {
  if (Number.isInteger(area)) {
    return String(area);
  }
  return area.toFixed(3);
}

function report(text) {
  const lines = [];
  let parallelograms = 0;
  for (const raw of text.split('\n')) {
    try {
      const parsed = parseCase(raw);
      if (parsed === null) {
        continue;
      }
      const [b1, b2, h] = parsed;
      const area = calculateTrapezoidArea(b1, b2, h);
      const kind = classifyTrapezoid(b1, b2);
      if (kind === 'parallelogram') {
        parallelograms += 1;
      }
      lines.push(`b1=${b1}, b2=${b2}, h=${h} -> area ${formatArea(area)} (${kind})`);
    } catch (err) {
      if (!(err instanceof TypeError)) {
        throw err;
      }
      lines.push(`"${raw.trim()}" -> rejected: ${err.message}`);
    }
  }
  lines.push(`parallelograms: ${parallelograms}`);
  return lines.join('\n');
}

function main() {
  const input = [
    '2 4 3',
    '5 5 2',
    '1.5 2.25 4',
    '',
    '3 -1 5',
    'eight 4 2',
    '6 7',
  ].join('\n');
  console.log(report(input));
}

main();

