const DAY_NAMES = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const SUNDAY = 0;
const SATURDAY = 6;

function isValidDate(date) {
  if (Object.prototype.toString.call(date) !== '[object Date]') {
    return false;
  }
  return !Number.isNaN(date.getTime());
}

function isWeekend(date) {
  if (!isValidDate(date)) {
    throw new TypeError('isWeekend expects a valid Date object');
  }
  const day = date.getUTCDay();
  if (day === SUNDAY) {
    return true;
  }
  return day === SATURDAY;
}

function dayName(date) {
  if (!isValidDate(date)) {
    throw new TypeError('dayName expects a valid Date object');
  }
  return DAY_NAMES[date.getUTCDay()];
}

function toIsoDay(date) {
  return date.toISOString().slice(0, 10);
}

function parseIsoDate(text) {
  if (typeof text !== 'string') {
    throw new TypeError('parseIsoDate expects a string');
  }
  const trimmed = text.trim();
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(trimmed);
  if (match === null) {
    throw new RangeError(`not an ISO date: ${text}`);
  }
  const [year, month, day] = match.slice(1).map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  if (toIsoDay(date) !== trimmed) {
    throw new RangeError(`no such calendar date: ${text}`);
  }
  return date;
}

function nextWeekend(date) {
  const cursor = new Date(date.getTime());
  while (!isWeekend(cursor)) {
    cursor.setUTCDate(cursor.getUTCDate() + 1);
  }
  return cursor;
}

function countWeekendDays(start, end) {
  if (start.getTime() > end.getTime()) {
    return countWeekendDays(end, start);
  }
  const cursor = new Date(start.getTime());
  let total = 0;
  while (cursor.getTime() <= end.getTime()) {
    if (isWeekend(cursor)) {
      total += 1;
    }
    cursor.setUTCDate(cursor.getUTCDate() + 1);
  }
  return total;
}

function describe(text) {
  const date = parseIsoDate(text);
  const label = isWeekend(date) ? 'weekend' : 'weekday';
  const upcoming = toIsoDay(nextWeekend(date));
  const suffix = upcoming === toIsoDay(date) ? 'today' : `next weekend day is ${upcoming}`;
  return `${toIsoDay(date)} is a ${dayName(date)} (${label}); ${suffix}`;
}

function main() {
  ['2023-10-28', '2023-10-27', '2023-10-29'].forEach((text) => {
    console.log(describe(text));
  });
  const october = countWeekendDays(parseIsoDate('2023-10-01'), parseIsoDate('2023-10-31'));
  console.log(`October 2023 contains ${october} weekend days`);
}

main();

module.exports = { isWeekend, dayName, parseIsoDate, nextWeekend, countWeekendDays, describe };

