function isFiniteNumber(value) {
  if (typeof value !== 'number') {
    return false;
  }
  return Number.isFinite(value);
}

function validateNumbers(numbers) {
  if (!Array.isArray(numbers)) {
    throw new TypeError('findMin expects an array of numbers');
  }
  if (numbers.length === 0) {
    throw new RangeError('findMin expects a non-empty array');
  }
  for (let i = 0; i < numbers.length; i += 1) {
    if (!isFiniteNumber(numbers[i])) {
      throw new TypeError('Element at index ' + i + ' is not a finite number');
    }
  }
}

function findMin(numbers) {
  validateNumbers(numbers);
  let smallest = numbers[0];
  for (let i = 1; i < numbers.length; i += 1) {
    if (numbers[i] < smallest) {
      smallest = numbers[i];
    }
  }
  return smallest;
}

function indexOfMin(numbers) {
  const smallest = findMin(numbers);
  for (let i = 0; i < numbers.length; i += 1) {
    if (numbers[i] === smallest) {
      return i;
    }
  }
  return -1;
}

function countMin(numbers) {
  const smallest = findMin(numbers);
  let total = 0;
  for (const value of numbers) {
    if (value === smallest) {
      total += 1;
    }
  }
  return total;
}

function parseNumbers(text) {
  return text
    .split(',')
    .map(function (part) {
      return part.trim();
    })
    .filter(function (part) {
      return part !== '';
    })
    .map(Number);
}

function describe(numbers) {
  const smallest = findMin(numbers);
  const position = indexOfMin(numbers);
  const repeats = countMin(numbers);
  const tail = repeats === 1 ? 'unique' : 'appears ' + repeats + ' times';
  return '[' + numbers.join(', ') + '] -> min ' + smallest +
    ' at index ' + position + ' (' + tail + ')';
}

const inputs = ['5, 1, 8, 2, 3', '10, 2, -5', '4, 4, 9, 4', '0.5, -0.25, 7', '', 'nope, 3'];
for (const line of inputs) {
  try {
    console.log(describe(parseNumbers(line)));
  } catch (error) {
    const kind = error instanceof RangeError ? 'empty input' : 'bad input';
    console.log('"' + line + '" rejected as ' + kind + ': ' + error.message);
  }
}

