function countWords(str) {
  if (typeof str !== 'string') {
    throw new TypeError('countWords expects a string');
  }
  let count = 0;
  let inWord = false;
  for (let i = 0; i < str.length; i += 1) {
    const isSeparator = str[i] === ' ';
    if (isSeparator) {
      inWord = false;
    } else if (inWord === false) {
      inWord = true;
      count += 1;
    }
  }
  return count;
}

function splitWords(str) {
  const words = [];
  let current = '';
  for (const ch of str) {
    if (ch === ' ') {
      if (current !== '') {
        words.push(current);
        current = '';
      }
    } else {
      current += ch;
    }
  }
  if (current !== '') {
    words.push(current);
  }
  return words;
}

function longestWord(str) {
  const words = splitWords(str);
  let best = '';
  for (const word of words) {
    if (word.length > best.length) {
      best = word;
    }
  }
  return best;
}

function describe(str) {
  const total = countWords(str);
  if (total === 0) {
    return 'no words';
  }
  const noun = total === 1 ? 'word' : 'words';
  return total + ' ' + noun + ', longest: "' + longestWord(str) + '"';
}

function main() {
  const samples = ['Hello world, how are you?', '  single word  ', '   ', 'one'];
  for (const sample of samples) {
    const shown = sample.trim() === '' ? '(blank)' : sample;
    console.log(shown + ' -> ' + describe(sample));
  }
}

main();

module.exports = { countWords, splitWords, longestWord, describe };

