function isByte(value) {
  if (typeof value !== 'number') {
    return false;
  }
  if (Number.isNaN(value)) {
    return false;
  }
  return Math.floor(value) === value && value >= 0 && value <= 255;
}

function toHexPair(value) {
  const hex = value.toString(16).toUpperCase();
  return hex.length === 1 ? '0' + hex : hex;
}

function rgbToHex(r, g, b) {
  const channels = [r, g, b];
  const names = ['red', 'green', 'blue'];
  for (let i = 0; i < channels.length; i += 1) {
    if (!isByte(channels[i])) {
      throw new RangeError(names[i] + ' must be an integer between 0 and 255');
    }
  }
  return '#' + channels.map(toHexPair).join('');
}

function hexToRgb(hex) {
  if (typeof hex !== 'string') {
    throw new TypeError('hex must be a string');
  }
  const body = hex.charAt(0) === '#' ? hex.slice(1) : hex;
  if (body.length !== 6) {
    throw new SyntaxError('hex must have six digits');
  }
  const parsed = [0, 2, 4].map(function (start) {
    const part = body.slice(start, start + 2);
    if (!/^[0-9a-fA-F]{2}$/.test(part)) {
      throw new SyntaxError('invalid hex digits: ' + part);
    }
    return parseInt(part, 16);
  });
  return { r: parsed[0], g: parsed[1], b: parsed[2] };
}

function parseRgbLiteral(text) {
  const match = /^rgb\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*\)$/.exec(text.trim());
  if (match === null) {
    throw new SyntaxError('expected rgb(r, g, b) but got: ' + text);
  }
  return {
    r: Number(match[1]),
    g: Number(match[2]),
    b: Number(match[3])
  };
}

function sameColor(first, second) {
  if (first.r !== second.r) {
    return false;
  }
  if (first.g !== second.g) {
    return false;
  }
  return first.b === second.b;
}

function isGray(rgb) {
  if (rgb.r !== rgb.g) {
    return false;
  }
  return rgb.g === rgb.b;
}

function describe(text) {
  const rgb = parseRgbLiteral(text);
  const hex = rgbToHex(rgb.r, rgb.g, rgb.b);
  const tone = isGray(rgb) ? 'gray' : 'colored';
  const status = sameColor(hexToRgb(hex), rgb) ? 'ok' : 'failed';
  return text + ' -> ' + hex + ' (' + tone + ', round-trip ' + status + ')';
}

const samples = [
  'rgb(255, 0, 0)',
  'rgb(0, 128, 255)',
  'rgb(17, 17, 17)',
  'rgb(0, 0, 0)',
  'rgb(300, 0, 0)'
];

samples.forEach(function (sample) {
  try {
