const VOWELS = 'aeiou';

function classifyChar(ch) {
  const lower = ch.toLowerCase();
  if (lower < 'a' || lower > 'z') {
    return 'other';
  }
  return VOWELS.indexOf(lower) === -1 ? 'consonant' : 'vowel';
}

function countVowelsAndConsonants(str) {
  if (typeof str !== 'string') {
    throw new TypeError('countVowelsAndConsonants expects a string');
  }
  const result = { vowels: 0, consonants: 0 };
  for (const ch of str) {
    const kind = classifyChar(ch);
    if (kind === 'vowel') {
      result.vowels += 1;
    } else if (kind === 'consonant') {
      result.consonants += 1;
    }
  }
  return result;
}

function dominantKind(counts) {
  if (counts.vowels === counts.consonants) {
    return 'balanced';
  }
  return counts.vowels > counts.consonants ? 'vowels' : 'consonants';
}

function letterRatio(counts) {
  const letters = counts.vowels + counts.consonants;
  if (letters === 0) {
    return null;
  }
  return counts.vowels / letters;
}

function formatReport(str, counts) {
  const ratio = letterRatio(counts);
  const ratioText = ratio === null ? 'n/a' : ratio.toFixed(2);
  const dominant = dominantKind(counts);
  const label = dominant === 'balanced' ? 'evenly split' : `more ${dominant}`;
  return `"${str}" -> vowels: ${counts.vowels}, consonants: ${counts.consonants}, ` +
    `vowel ratio: ${ratioText} (${label})`;
}

function richestSample(samples) {
  return samples.reduce((best, current) => {
    const bestCounts = countVowelsAndConsonants(best);
    const currentCounts = countVowelsAndConsonants(current);
    const bestTotal = bestCounts.vowels + bestCounts.consonants;
    const currentTotal = currentCounts.vowels + currentCounts.consonants;
    if (currentTotal === bestTotal) {
      return best.length <= current.length ? best : current;
    }
    return currentTotal > bestTotal ? current : best;
  });
}

function main() {
  const samples = ['Hello World', 'JavaScript', 'Rhythm', 'Eerie aioli', '1234!?'];
  const lines = samples.map((sample) => formatReport(sample, countVowelsAndConsonants(sample)));
  lines.push(`Most letters: "${richestSample(samples)}"`);
  console.log(lines.join('\n'));
}

if (typeof module !== 'undefined') {
  module.exports = {
    countVowelsAndConsonants,
    dominantKind,
    letterRatio,
    formatReport,
    richestSample,
  };
  if (require.main === module) {
    main();
  }
} else {
  main();
}

