'use strict';

function validateNumber(value, label) {
  if (typeof value !== 'number') {
    throw new TypeError(`${label} must be a number`);
  }
  if (!Number.isInteger(value)) {
    throw new RangeError(`${label} must be a whole number`);
  }
}

function validateTime(hours, minutes) {
  validateNumber(hours, 'hours');
  validateNumber(minutes, 'minutes');
  if (hours < 0 || hours > 12) {
    throw new RangeError(`hours out of range: ${hours}`);
  }
  if (minutes < 0 || minutes > 59) {
    throw new RangeError(`minutes out of range: ${minutes}`);
  }
}

function normalizeHours(hours) {
  return hours === 12 ? 0 : hours;
}

function clockAngle(hours, minutes) {
  validateTime(hours, minutes);
  const h = normalizeHours(hours);
  const hourAngle = h * 30 + minutes * 0.5;
  const minuteAngle = minutes * 6;
  const diff = Math.abs(hourAngle - minuteAngle);
  return diff > 180 ? 360 - diff : diff;
}

function parseTime(text) {
  const parts = String(text).trim().split(':');
  if (parts.length !== 2) {
    throw new Error(`malformed time, expected H:MM but got "${text}"`);
  }
  if (parts[1].length !== 2) {
    throw new Error(`minutes must have two digits in "${text}"`);
  }
  return { hours: Number(parts[0]), minutes: Number(parts[1]) };
}

function formatTime(hours, minutes) {
  const h = normalizeHours(hours);
  const label = h === 0 ? 12 : h;
  return `${label}:${String(minutes).padStart(2, '0')}`;
}

function describeAngle(angle) {
  if (angle === 0) {
    return 'hands overlap';
  }
  if (angle === 180) {
    return 'hands point in opposite directions';
  }
  if (angle === 90) {
    return 'hands form a right angle';
  }
  return `${angle} degrees apart`;
}

function report(times) {
  return times.map((text) => {
    const { hours, minutes } = parseTime(text);
    const angle = clockAngle(hours, minutes);
    return `${formatTime(hours, minutes)}  angle=${angle}  (${describeAngle(angle)})`;
  });
}

function main() {
  const schedule = ['3:00', '12:30', '0:00', '6:00', '9:45', '5:24'];
  for (const line of report(schedule)) {
    console.log(line);
  }
}

main();

module.exports = { clockAngle, parseTime, formatTime, describeAngle, report };

