'use strict';

function isPlainObject(value) {
  if (typeof value !== 'object') {
    return false;
  }
  if (value === null) {
    return false;
  }
  return !Array.isArray(value);
}

function validateInput(arr, key) {
  if (!Array.isArray(arr)) {
    throw new TypeError('arr must be an array');
  }
  if (typeof key !== 'string') {
    throw new TypeError('key must be a string');
  }
  if (key === '') {
    throw new RangeError('key must not be empty');
  }
}

function getUniqueValuesByKey(arr, key) {
  validateInput(arr, key);
  const seen = new Set();
  const unique = [];
  for (const item of arr) {
    if (!isPlainObject(item)) {
      continue;
    }
    if (!Object.prototype.hasOwnProperty.call(item, key)) {
      continue;
    }
    const value = item[key];
    if (!seen.has(value)) {
      seen.add(value);
      unique.push(value);
    }
  }
  return unique;
}

function countMissingKey(arr, key) {
  validateInput(arr, key);
  let missing = 0;
  for (const item of arr) {
    if (!isPlainObject(item)) {
      missing += 1;
    } else if (item[key] === undefined) {
      missing += 1;
    }
  }
  return missing;
}

function formatValue(value) {
  if (value === null) {
    return 'null';
  }
  if (typeof value === 'string') {
    return `'${value}'`;
  }
  return String(value);
}

function report(arr, key) {
  const values = getUniqueValuesByKey(arr, key);
  const missing = countMissingKey(arr, key);
  const listed = values.map(formatValue).join(', ');
  const tail = missing === 0 ? '' : ` (${missing} record(s) without '${key}')`;
  return `${key}: [${listed}]${tail}`;
}

