function capitalizeWord(word) {
  if (word === '') {
    return '';
  }
  const first = word[0];
  const upper = first.toUpperCase();
  if (upper === first) {
    return word;
  }
  return upper + word.slice(1);
}

function capitalizeWords(str) {
  if (typeof str !== 'string') {
    throw new TypeError('capitalizeWords expects a string');
  }
  const words = str.split(' ');
  const out = [];
  for (let i = 0; i < words.length; i += 1) {
    out.push(capitalizeWord(words[i]));
  }
  return out.join(' ');
}

function countWords(str) {
  let total = 0;
  for (const word of str.split(' ')) {
    if (word !== '') {
      total += 1;
    }
  }
  return total;
}

function alreadyCapitalized(str) {
  return capitalizeWords(str) === str;
}

function describe(str) {
  const result = capitalizeWords(str);
  const words = countWords(str);
  const noun = words === 1 ? 'word' : 'words';
  const note = alreadyCapitalized(str) ? ' (unchanged)' : '';
  return `${words} ${noun}: "${result}"${note}`;
}

function main() {
  const samples = [
    'hello world',
    'javascript is fun',
    'Already Capitalized Text',
    '  spaced   out  ',
    ''
  ];

  for (const sample of samples) {
    if (sample === '') {
      console.log('empty input -> ""');
      continue;
    }
    console.log(describe(sample));
  }

  const bad = 42;
  try {
    capitalizeWords(bad);
  } catch (err) {
    if (err instanceof TypeError) {
      console.log(`rejected ${typeof bad} input: ${err.message}`);
    } else {
      throw err;
    }
  }
}

main();

module.exports = { capitalizeWords, capitalizeWord, countWords, describe };

