function runLengthEncode(str) {
  if (typeof str !== 'string') {
    throw new TypeError('runLengthEncode expects a string');
  }
  if (str.length === 0) {
    return '';
  }
  const parts = [];
  let runChar = str[0];
  let runLength = 1;
  for (let i = 1; i < str.length; i += 1) {
    const ch = str[i];
    if (ch === runChar) {
      runLength += 1;
    } else {
      parts.push(String(runLength) + runChar);
      runChar = ch;
      runLength = 1;
    }
  }
  parts.push(String(runLength) + runChar);
  return parts.join('');
}

function runLengthDecode(encoded) {
  if (typeof encoded !== 'string') {
    throw new TypeError('runLengthDecode expects a string');
  }
  let out = '';
  let digits = '';
  for (const ch of encoded) {
    if (ch >= '0' && ch <= '9') {
      digits += ch;
    } else {
      if (digits === '') {
        throw new Error('missing count before "' + ch + '"');
      }
      out += ch.repeat(Number(digits));
      digits = '';
    }
  }
  if (digits !== '') {
    throw new Error('trailing count "' + digits + '" without a character');
  }
  return out;
}

function describeRun(part) {
  const count = Number(part.slice(0, -1));
  const ch = part.slice(-1);
  const label = count === 1 ? 'time' : 'times';
  return ch + ' x ' + count + ' ' + label;
}

function report(str) {
  const encoded = runLengthEncode(str);
  const roundTrip = runLengthDecode(encoded);
  const status = roundTrip === str ? 'ok' : 'MISMATCH';
  const runs = encoded.match(/\d+./g) || [];
  const summary = runs.map(describeRun).join(', ');
  return 'input: ' + (str.length === 0 ? '(empty)' : str) +
    '\nencoded: ' + (encoded.length === 0 ? '(empty)' : encoded) +
    '\nruns: ' + (summary.length === 0 ? '(none)' : summary) +
    '\nround trip: ' + status;
}

function main() {
  const samples = [
    'AAAABBBCCDAA',
    'WWWWWWWWWWWWBWWWWWWWWWWWWBBBWWWWWWWWWWWWWWWWWWWWWWWWB',
    'abc',
    ''
  ];
  for (const sample of samples) {
    console.log(report(sample));
    console.log('---');
  }
}

main();

