function stringToWords(str) {
  if (str === null) {
    return [];
  }

  if (typeof str !== 'string') {
    return [];
  }

  let words = [];
  let currentWord = '';
  let inWord = false;

  for (let i = 0; i < str.length; i++) {
    const char = str[i];

    if (char === ' ') {
      if (inWord === true) {
        words.push(currentWord);
        currentWord = '';
        inWord = false;
      }
    } else {
      currentWord += char;
      if (inWord === false) {
        inWord = true;
      }
    }
  }

  if (currentWord !== '') {
    words.push(currentWord);
  }

  const result = [];
  for (let i = 0; i < words.length; i++) {
    if (words[i] !== '') {
      result.push(words[i]);
    }
  }

  if (result.length === 0 && str.trim() === '') {
    return [];
  }

  return result;
}

