function isPlainRecord(item) {
  if (item === null) {
    return false;
  }
  return typeof item === 'object';
}

function filterObjectsByKey(arr, key, value) {
  if (!Array.isArray(arr)) {
    throw new TypeError('filterObjectsByKey: arr must be an array');
  }
  if (typeof key !== 'string') {
    throw new TypeError('filterObjectsByKey: key must be a string');
  }
  if (key.length === 0) {
    throw new TypeError('filterObjectsByKey: key must not be empty');
  }
  const result = [];
  for (const item of arr) {
    if (!isPlainRecord(item)) {
      continue;
    }
    if (!Object.prototype.hasOwnProperty.call(item, key)) {
      continue;
    }
    if (item[key] === value) {
      result.push(item);
    }
