function objectToKeyValuePairs(obj) {
  if (obj === null) {
    throw new TypeError('objectToKeyValuePairs expects a non-null object');
  }
  if (typeof obj !== 'object') {
    throw new TypeError('objectToKeyValuePairs expects an object');
  }
  if (Array.isArray(obj)) {
    throw new TypeError('objectToKeyValuePairs expects a plain object, not an array');
  }
  const pairs = [];
  for (const key of Object.keys(obj)) {
    pairs.push([key, obj[key]]);
  }
  return pairs;
}

function findValue(pairs, key) {
  for (const pair of pairs) {
    if (pair[0] === key) {
      return pair[1];
    }
  }
  return undefined;
}

function keyValuePairsToObject(pairs) {
  const result = {};
  for (const pair of pairs) {
    if (pair.length !== 2) {
      throw new TypeError('each pair must have exactly two elements');
    }
    result[pair[0]] = pair[1];
  }
  return result;
}

function formatValue(value) {
  if (value === null) {
    return 'null';
  }
  if (typeof value === 'string') {
    return '"' + value + '"';
  }
  if (typeof value === 'object') {
    return Array.isArray(value) ? '[' + value.map(formatValue).join(', ') + ']' : '{...}';
  }
  return String(value);
}

function formatPairs(pairs) {
  if (pairs.length === 0) {
    return '(no entries)';
  }
  return pairs.map(pair => pair[0] + ' => ' + formatValue(pair[1])).join('\n');
}

function samePairSets(a, b) {
  if (a.length !== b.length) {
    return false;
  }
  return a.every(pair => findValue(b, pair[0]) === pair[1]);
}

function main() {
  const samples = [{ a: 1, b: 2 }, {}, { name: 'ada', tags: ['math', 'code'], active: false, note: null }];
  for (const sample of samples) {
    const pairs = objectToKeyValuePairs(sample);
    console.log(formatPairs(pairs));
    const rebuilt = objectToKeyValuePairs(keyValuePairsToObject(pairs));
    console.log('round trip stable: ' + samePairSets(pairs, rebuilt));
    console.log('---');
  }
  try {
    objectToKeyValuePairs([1, 2, 3]);
  } catch (err) {
    console.log('rejected array input: ' + err.message);
  }
}

main();

