const MONTH_LENGTHS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
const MONTH_NAMES = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December'
];

function isLeapYear(year) {
  if (year % 400 === 0) return true;
  if (year % 100 === 0) return false;
  return year % 4 === 0;
}

function requireInteger(value, name) {
  if (typeof value !== 'number') {
    throw new TypeError(`${name} must be a number`);
  }
  if (Math.trunc(value) !== value) {
    throw new RangeError(`${name} must be an integer`);
  }
  return value;
}

function daysInMonth(year, month) {
  requireInteger(year, 'year');
  requireInteger(month, 'month');
  if (month < 1 || month > 12) {
    throw new RangeError('month must be in the range 1..12');
  }
  if (month === 2 && isLeapYear(year)) {
    return 29;
  }
  return MONTH_LENGTHS[month - 1];
}

function monthName(month) {
  return MONTH_NAMES[month - 1];
}

function daysInYear(year) {
  let total = 0;
  for (let month = 1; month <= 12; month += 1) {
    total += daysInMonth(year, month);
  }
  return total;
}

function parseYearMonth(text) {
  const parts = text.split('-');
  if (parts.length !== 2) {
    throw new SyntaxError(`expected YYYY-MM, got "${text}"`);
  }
  const year = Number(parts[0]);
  const month = Number(parts[1]);
  if (Number.isNaN(year) || Number.isNaN(month)) {
    throw new SyntaxError(`non-numeric field in "${text}"`);
  }
  return { year, month };
}

function describe(text) {
  const { year, month } = parseYearMonth(text);
  const days = daysInMonth(year, month);
  const suffix = days === 29 ? ' (leap day included)' : '';
  return `${monthName(month)} ${year}: ${days} days${suffix}`;
}

function main() {
  const samples = ['2023-02', '2024-02', '2000-02', '1900-02', '2023-04', '2023-12'];
  for (const sample of samples) {
    console.log(describe(sample));
  }
  for (const year of [1900, 2000, 2023, 2024]) {
    const total = daysInYear(year);
    const kind = total === 366 ? 'leap' : 'common';
    console.log(`${year} is a ${kind} year with ${total} days`);
  }
}

main();

