function validateDimension(value, name) {
  if (typeof value !== 'number') {
    throw new TypeError(name + ' must be a number, received ' + typeof value);
  }
  if (!Number.isFinite(value)) {
    throw new RangeError(name + ' must be a finite number');
  }
  if (value <= 0) {
    throw new RangeError(name + ' must be positive, received ' + value);
  }
  return value;
}

function getRectangleProps(width, height) {
  const w = validateDimension(width, 'width');
  const h = validateDimension(height, 'height');
  return { area: w * h, perimeter: 2 * (w + h) };
}

function classifyRectangle(width, height) {
  if (width === height) {
    return 'square';
  }
  const ratio = width > height ? width / height : height / width;
  if (ratio === 2) {
    return 'domino';
  }
  return 'oblong';
}

function parseDimensions(text) {
  const parts = String(text).split('x');
  if (parts.length !== 2) {
    throw new SyntaxError('expected format "WIDTHxHEIGHT", received "' + text + '"');
  }
  const numbers = parts.map(function (part) {
    const trimmed = part.trim();
    if (trimmed === '') {
      throw new SyntaxError('missing dimension in "' + text + '"');
    }
    return Number(trimmed);
  });
  return { width: numbers[0], height: numbers[1] };
}

function formatReport(width, height) {
  const props = getRectangleProps(width, height);
  const kind = classifyRectangle(width, height);
  const note = props.area === props.perimeter ? ' (area equals perimeter)' : '';
  return width + 'x' + height + ' -> area ' + props.area +
    ', perimeter ' + props.perimeter + ', ' + kind + note;
}

function main() {
  const inputs = ['5x10', '2x2', '4x4', '3x6', '7x-1', '9'];
  inputs.forEach(function (input) {
    try {
      const dims = parseDimensions(input);
      console.log(formatReport(dims.width, dims.height));
    } catch (err) {
      const label = err.name === 'SyntaxError' ? 'bad input' : 'invalid size';
      console.log(input + ' -> ' + label + ': ' + err.message);
    }
  });
}

main();

module.exports = { getRectangleProps, classifyRectangle, parseDimensions, formatReport };

