function validateInterval(interval, label) {
  if (!Array.isArray(interval)) {
    throw new TypeError(label + ' must be an array');
  }
  if (interval.length !== 2) {
    throw new RangeError(label + ' must contain exactly two numbers');
  }
  const [start, end] = interval;
  if (typeof start !== 'number') {
    throw new TypeError(label + ' start must be a number');
  }
  if (typeof end !== 'number') {
    throw new TypeError(label + ' end must be a number');
  }
  if (!Number.isFinite(start) || !Number.isFinite(end)) {
    throw new RangeError(label + ' must contain finite numbers');
  }
  if (start >= end) {
    throw new RangeError(label + ' must satisfy start < end');
  }
  return { start, end };
}

function checkOverlap(interval1, interval2) {
  const a = validateInterval(interval1, 'interval1');
  const b = validateInterval(interval2, 'interval2');
  return a.start < b.end && b.start < a.end;
}

function overlapLength(interval1, interval2) {
  const a = validateInterval(interval1, 'interval1');
  const b = validateInterval(interval2, 'interval2');
  const shared = Math.min(a.end, b.end) - Math.max(a.start, b.start);
  return shared > 0 ? shared : 0;
}

function describeRelation(interval1, interval2) {
  const a = validateInterval(interval1, 'interval1');
  const b = validateInterval(interval2, 'interval2');
  const shared = overlapLength(interval1, interval2);
  if (shared === 0) {
    if (a.end === b.start) {
      return 'touching';
    }
    if (b.end === a.start) {
      return 'touching';
    }
    return 'disjoint';
  }
  if (a.start === b.start) {
    if (a.end === b.end) {
      return 'identical';
    }
  }
  if (a.start <= b.start && b.end <= a.end) {
    return 'interval2 inside interval1';
  }
  if (b.start <= a.start && a.end <= b.end) {
    return 'interval1 inside interval2';
  }
  return 'partial overlap of ' + shared;
}

function formatReport(pair) {
  const [first, second] = pair;
  const flag = checkOverlap(first, second) ? 'yes' : 'no ';
  const left = '[' + first.join(', ') + ']';
  const right = '[' + second.join(', ') + ']';
  return left + ' vs ' + right + ' -> overlap: ' + flag + ' (' + describeRelation(first, second) + ')';
}

function main() {
  const pairs = [
    [[1, 5], [3, 7]],
    [[1, 5], [6, 10]],
    [[1, 5], [5, 9]],
    [[0, 10], [2, 4]],
    [[2, 8], [2, 8]],
    [[-4, -1], [-2, 3]]
  ];
  for (const pair of pairs) {
    console.log(formatReport(pair));
  }
  const overlapping = pairs.filter((pair) => checkOverlap(pair[0], pair[1]));
  console.log('overlapping pairs: ' + overlapping.length + ' of ' + pairs.length);
}

main();

module.exports = { checkOverlap, overlapLength, describeRelation, formatReport };

