  if (typeof choice != 'string') {
    throw new TypeError('A choice must be given as a string');
  }
  const cleaned = choice.trim().toLowerCase();
  if (VALID_CHOICES.indexOf(cleaned) == -1) {
    throw new RangeError('Unknown choice: ' + choice);
  }
  return cleaned;
}

