function findIndexById(records, id) {
  if (!Array.isArray(records)) {
    throw new TypeError('records must be an array');
  }
  if (!Number.isFinite(id)) {
    throw new TypeError('id must be a finite number');
  }
  for (let i = 0; i < records.length; i += 1) {
    const record = records[i];
    if (record && record.id === id) {
      return i;
    }
  }
  return -1;
}

function findRecordById(records, id) {
  const index = findIndexById(records, id);
  if (index === -1) {
    return null;
  }
  return records[index];
}

function removeRecordById(records, id) {
  const index = findIndexById(records, id);
  if (index === -1) {
    return false;
  }
  records.splice(index, 1);
  return true;
}

function upsertRecord(records, record) {
  const existing = findRecordById(records, record.id);
  if (existing === null) {
    records.push(record);
    return 'inserted';
  }
  Object.assign(existing, record);
  return 'updated';
}

function describeRecord(record) {
  if (record === null) {
    return 'not found';
  }
  return '#' + record.id + ' ' + (record.name || '<unnamed>');
}

function formatTable(records) {
  return records.map(describeRecord).join(' | ');
}

function main() {
  const records = [
    { id: 1, name: 'A' },
    { id: 2, name: 'B' },
    { id: 7, name: 'C' }
  ];

  console.log(describeRecord(findRecordById(records, 2)));
  console.log(describeRecord(findRecordById(records, 3)));

  const newStatus = upsertRecord(records, { id: 3, name: 'D' });
  if (newStatus === 'inserted') {
    console.log('added ' + describeRecord(findRecordById(records, 3)));
  }

  const renameStatus = upsertRecord(records, { id: 1, name: 'A-renamed' });
  if (renameStatus === 'updated') {
    console.log('renamed to ' + describeRecord(findRecordById(records, 1)));
  }

  if (removeRecordById(records, 7)) {
    console.log('removed record 7');
  }
  console.log(formatTable(records));

  try {
    findRecordById(records, '3');
  } catch (err) {
    console.log('rejected: ' + err.message);
  }
}

main();

